svg.script:
// ===== MATH =====
const X3=[1,0,0],Y3=[0,1,0],Z3=[0,0,0],QI=[0,0,0,1];
function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function smooth(t){t=clamp(t,0,1);return t*t*(3-2*t);}
function lerpAngle(a,b,t){let d=(b-a)%(Math.PI*2);if(d>Math.PI)d-=Math.PI*2;if(d<-Math.PI)d+=Math.PI*2;return a+d*t;}
function wrapAng(a){a=(a+Math.PI)%(Math.PI*2);if(a<0)a+=Math.PI*2;return a-Math.PI;}
function rnd(a,b){return a+Math.random()*(b-a);}
function fract(v){return v-Math.floor(v);}
const V3={
 sub:(a,b)=>[a[0]-b[0],a[1]-b[1],a[2]-b[2]],add:(a,b)=>[a[0]+b[0],a[1]+b[1],a[2]+b[2]],
 scale:(a,s)=>[a[0]*s,a[1]*s,a[2]*s],dot:(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2],
 cross:(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],
 len:a=>Math.sqrt(a[0]*a[0]+a[1]*a[1]+a[2]*a[2]),
 norm:function(a){const l=V3.len(a)||1;return [a[0]/l,a[1]/l,a[2]/l];},
 lerp:(a,b,t)=>[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t]};
const Q={
 mul:function(a,b){const ax=a[0],ay=a[1],az=a[2],aw=a[3],bx=b[0],by=b[1],bz=b[2],bw=b[3];
  return [ax*bw+aw*bx+ay*bz-az*by,ay*bw+aw*by+az*bx-ax*bz,az*bw+aw*bz+ax*by-ay*bx,aw*bw-ax*bx-ay*by-az*bz];},
 conj:a=>[-a[0],-a[1],-a[2],a[3]],
 norm:function(a){const l=Math.hypot(a[0],a[1],a[2],a[3])||1;return [a[0]/l,a[1]/l,a[2]/l,a[3]/l];},
 axisAngle:function(x,y,z,ang){const l=V3.len([x,y,z])||1,s=Math.sin(ang/2)/l;return [x*s,y*s,z*s,Math.cos(ang/2)];},
 fromEuler:function(rx,ry,rz){return Q.mul(Q.axisAngle(0,0,1,rz),Q.mul(Q.axisAngle(0,1,0,ry),Q.axisAngle(1,0,0,rx)));},
 fromYto:function(d){const dot=Math.max(-1,Math.min(1,d[1]));if(dot>0.99995)return [0,0,0,1];
  if(dot<-0.99995)return Q.axisAngle(1,0,0,Math.PI);const ax=V3.norm(V3.cross([0,1,0],d));return Q.axisAngle(ax[0],ax[1],ax[2],Math.acos(dot));},
 rotVec:function(q,v){const x=q[0],y=q[1],z=q[2],w=q[3];const uv=V3.cross([x,y,z],v),uuv=V3.cross([x,y,z],uv);
  return V3.add(V3.add(v,V3.scale(uv,2*w)),V3.scale(uuv,2));},
 rotVecConj:function(q,v){return Q.rotVec(Q.conj(q),v);}};
const M4={
 ident:function(){const m=new Float32Array(16);m[0]=m[5]=m[10]=m[15]=1;return m;},
 fromQuatPos:function(q,p,out){out=out||new Float32Array(16);const x=q[0],y=q[1],z=q[2],w=q[3],x2=x+x,y2=y+y,z2=z+z;
  const xx=x*x2,xy=x*y2,xz=x*z2,yy=y*y2,yz=y*z2,zz=z*z2,wx=w*x2,wy=w*y2,wz=w*z2;
  out[0]=1-(yy+zz);out[1]=xy+wz;out[2]=xz-wy;out[3]=0;out[4]=xy-wz;out[5]=1-(xx+zz);out[6]=yz+wx;out[7]=0;
  out[8]=xz+wy;out[9]=yz-wx;out[10]=1-(xx+yy);out[11]=0;out[12]=p[0];out[13]=p[1];out[14]=p[2];out[15]=1;return out;},
 mul:function(a,b,out){out=out||new Float32Array(16);for(let c=0;c<4;c++){const b0=b[c*4],b1=b[c*4+1],b2=b[c*4+2],b3=b[c*4+3];
  for(let r=0;r<4;r++)out[c*4+r]=a[r]*b0+a[4+r]*b1+a[8+r]*b2+a[12+r]*b3;}return out;},
 perspective:function(fovy,asp,n,f,out){out=out||new Float32Array(16);const t=1/Math.tan(fovy/2);out.fill(0);
  out[0]=t/asp;out[5]=t;out[10]=(f+n)/(n-f);out[11]=-1;out[14]=(2*f*n)/(n-f);return out;},
 lookAt:function(eye,ct,up,out){out=out||new Float32Array(16);const z=V3.norm(V3.sub(eye,ct)),x=V3.norm(V3.cross(up,z)),y=V3.cross(z,x);
  out[0]=x[0];out[1]=y[0];out[2]=z[0];out[3]=0;out[4]=x[1];out[5]=y[1];out[6]=z[1];out[7]=0;out[8]=x[2];out[9]=y[2];out[10]=z[2];out[11]=0;
  out[12]=-V3.dot(x,eye);out[13]=-V3.dot(y,eye);out[14]=-V3.dot(z,eye);out[15]=1;return out;}};

// ===== SKELETON (same 19 bones incl. gun) =====
const BONES=[
 {name:'hips',parent:-1,pos:[0,0.96,0],dir:[0,1,0],len:0.14},
 {name:'spine',parent:0,pos:[0,1.085,0],dir:[0,1,0],len:0.15},
 {name:'chest',parent:1,pos:[0,1.235,0],dir:[0,1,0],len:0.21},
 {name:'neck',parent:2,pos:[0,1.445,0],dir:[0,1,0],len:0.08},
 {name:'head',parent:3,pos:[0,1.525,0],dir:[0,1,0],len:0.09},
 {name:'helmet',parent:4,pos:[0,1.615,0],dir:[0,1,0],len:0.07},
 {name:'lArm',parent:2,pos:[-0.205,1.42,0],dir:[-0.221,-0.975,0],len:0.27},
 {name:'lFore',parent:6,pos:[-0.265,1.157,0],dir:[-0.221,-0.975,0],len:0.25},
 {name:'lHand',parent:7,pos:[-0.32,0.915,0],dir:[-0.221,-0.975,0],len:0.09},
 {name:'rArm',parent:2,pos:[0.205,1.42,0],dir:[0.221,-0.975,0],len:0.27},
 {name:'rFore',parent:9,pos:[0.265,1.157,0],dir:[0.221,-0.975,0],len:0.25},
 {name:'rHand',parent:10,pos:[0.32,0.915,0],dir:[0.221,-0.975,0],len:0.09},
 {name:'gun',parent:11,pos:[0.308,0.868,0.03],dir:[0,-0.35,0.937],len:0.62},
 {name:'lThigh',parent:0,pos:[-0.095,0.97,0],dir:[0,-1,0],len:0.42},
 {name:'lShin',parent:13,pos:[-0.095,0.55,0],dir:[0,-1,0],len:0.4},
 {name:'lFoot',parent:14,pos:[-0.095,0.15,0],dir:[0,0.08,0.997],len:0.13},
 {name:'rThigh',parent:0,pos:[0.095,0.97,0],dir:[0,-1,0],len:0.42},
 {name:'rShin',parent:16,pos:[0.095,0.55,0],dir:[0,-1,0],len:0.4},
 {name:'rFoot',parent:17,pos:[0.095,0.15,0],dir:[0,0.08,0.997],len:0.13}];
const NB=BONES.length,BIDX={};for(let i=0;i<NB;i++)BIDX[BONES[i].name]=i;
const REST_Q=BONES.map(b=>Q.fromYto(V3.norm(b.dir)));
const REST_LQ=BONES.map((b,i)=>b.parent<0?REST_Q[i].slice():Q.norm(Q.mul(Q.conj(REST_Q[b.parent]),REST_Q[i])));
const REST_LOFF=BONES.map((b,i)=>b.parent<0?[0,0,0]:Q.rotVecConj(REST_Q[b.parent],V3.sub(b.pos,BONES[b.parent].pos)));
const _bq=new Array(NB),_bp=new Array(NB),_tm=new Float32Array(16);
function computePose(pose,ePos,eYaw,outMats,outPos){
 const yawQ=Q.axisAngle(0,1,0,eYaw),root=pose.root||Z3;
 for(let i=0;i<NB;i++){const b=BONES[i],d=pose.rot?pose.rot[b.name]:null;
  const dq=d?Q.fromEuler(d[0],d[1],d[2]):QI,lq=(dq===QI)?REST_LQ[i]:Q.norm(Q.mul(REST_LQ[i],dq));let wq,wp;
  if(b.parent<0){wq=Q.norm(Q.mul(yawQ,lq));wp=V3.add(ePos,Q.rotVec(yawQ,V3.add(b.pos,root)));}
  else{const pq=_bq[b.parent];wq=Q.norm(Q.mul(pq,lq));wp=V3.add(_bp[b.parent],Q.rotVec(pq,REST_LOFF[i]));}
  _bq[i]=wq;_bp[i]=wp;M4.fromQuatPos(wq,wp,_tm);outMats.set(_tm,i*16);
  if(outPos){outPos[i*3]=wp[0];outPos[i*3+1]=wp[1];outPos[i*3+2]=wp[2];}}
}
function copyPose(p){const ro={};for(const k in p.rot){const v=p.rot[k];ro[k]=[v[0],v[1],v[2]];}return {root:[p.root[0],p.root[1],p.root[2]],rot:ro};}
function mixPose(a,b,t){const ro={},ka=a.rot||{},kb=b.rot||{};
 for(const k in ka){const va=ka[k],vb=kb[k]||Z3;ro[k]=[va[0]+(vb[0]-va[0])*t,va[1]+(vb[1]-va[1])*t,va[2]+(vb[2]-va[2])*t];}
 for(const k in kb)if(!(k in ka)){const v=kb[k];ro[k]=[v[0]*t,v[1]*t,v[2]*t];}
 return {root:V3.lerp(a.root||Z3,b.root||Z3,t),rot:ro};}
function ov(base,root,over){const r={};for(const k in base.rot)r[k]=base.rot[k];for(const k in over)r[k]=over[k];return {root:root||base.root,rot:r};}

// ===== FIGHT ANIMATION (procedural poses; blended by timeline) =====
function stance(t){
 const bn=Math.sin(t*5.2),b2=Math.sin(t*2.6+1);
 return {root:[0,-0.11+0.016*bn,0],rot:{
  hips:[0.05,0,0],spine:[0.14+0.012*bn,0.10,0],chest:[0.10,0.10,0.012*b2],neck:[-0.14,-0.08,0],head:[-0.05,-0.08,0],helmet:[0,0,0],
  rArm:[0.9,0,0],rFore:[1.9,0,0],rHand:[0,0,0],lArm:[0.85,0,0.15],lFore:[1.9,0,0],lHand:[0,0,0],gun:[0,0,0],
  rThigh:[-0.30,0,-0.08],rShin:[0.45,0,0],rFoot:[-0.12,0,0],lThigh:[0.16,0,0.10],lShin:[0.40,0,0],lFoot:[-0.12,0,0]}};}
const S0=stance(0);
const POSES={
 stance:S0,
 jabW:ov(S0,null,{rArm:[0.7,0,0],rFore:[2.2,0,0],chest:[0.1,0.25,0],spine:[0.14,0.2,0]}),
 jab:ov(S0,[0,-0.11,0.12],{rArm:[1.5,0.05,0],rFore:[0.08,0,0],chest:[0.08,-0.35,0],spine:[0.14,-0.2,0],head:[-0.05,0.2,0]}),
 crossW:ov(S0,null,{lArm:[0.6,0,0.15],lFore:[2.3,0,0],chest:[0.1,-0.25,0],spine:[0.14,-0.15,0]}),
 cross:ov(S0,[0,-0.12,0.18],{lArm:[1.5,-0.05,0.05],lFore:[0.08,0,0],chest:[0.08,0.5,0],spine:[0.14,0.3,0],hips:[0.05,0.3,0],head:[-0.05,-0.3,0]}),
 hookW:ov(S0,null,{rArm:[1.2,-0.9,0],rFore:[1.2,0,0],chest:[0.1,0.7,0],spine:[0.14,0.4,0]}),
 hook:ov(S0,[0,-0.14,0.15],{rArm:[1.3,0.9,0],rFore:[1.2,0,0],chest:[0.1,-0.8,0],spine:[0.14,-0.5,0],hips:[0.05,-0.3,0]}),
 kickW:ov(S0,[0,-0.12,0],{rThigh:[-0.2,0,-0.1],rShin:[1.4,0,0],lThigh:[0.1,0,0.08],lShin:[0.3,0,0],spine:[0.0,0.1,0],chest:[-0.05,0.1,0]}),
 kick:ov(S0,[0,-0.10,0],{rThigh:[-1.45,0,-0.12],rShin:[0.15,0,0],rFoot:[0.4,0,0],lThigh:[0.12,0,0.06],lShin:[0.25,0,0],spine:[-0.28,0.1,0],chest:[-0.2,0.1,0],head:[0.1,0,0],rArm:[0.3,0,-0.5],lArm:[0.6,0,0.7]}),
 chargeW:ov(S0,[0,-0.32,0],{rArm:[0.35,0,0],rFore:[1.9,0,0],lArm:[0.35,0,0.1],lFore:[1.9,0,0],rThigh:[-0.9,0,-0.15],rShin:[1.5,0,0],lThigh:[-0.6,0,0.15],lShin:[1.4,0,0],spine:[0.3,0,0],chest:[0.2,0,0]}),
 thrust:ov(S0,[0,-0.2,0.1],{rArm:[1.5,0.0,0],rFore:[0.0,0,0],lArm:[1.5,0.05,0],lFore:[0.0,0,0],rThigh:[-0.7,0,-0.1],rShin:[0.8,0,0],lThigh:[0.35,0,0.1],lShin:[0.5,0,0],spine:[0.2,0,0],chest:[0.1,0,0]}),
 rise:ov(S0,[0,0.12,0.1],{rArm:[3.0,0,-0.1],rFore:[0.1,0,0],lArm:[2.9,0,0.2],lFore:[0.1,0,0],rThigh:[-0.5,0,-0.1],rShin:[0.7,0,0],lThigh:[-0.2,0,0.1],lShin:[0.6,0,0],spine:[-0.2,0,0],chest:[-0.25,0,0],head:[-0.3,0,0]}),
 block:ov(S0,[0,-0.2,0],{rArm:[1.2,-0.3,0],rFore:[2.3,0,0],lArm:[1.2,0.3,0.1],lFore:[2.3,0,0],spine:[0.3,0,0],chest:[0.2,0,0],head:[0.1,0,0]}),
 hit:ov(S0,[0,-0.08,-0.12],{spine:[-0.25,0,0.1],chest:[-0.2,0,0],head:[-0.4,0,0],rArm:[0.2,0,-0.5],lArm:[0.3,0,0.7],rFore:[0.6,0,0],lFore:[0.6,0,0]}),
 jump:ov(S0,[0,0,0],{rThigh:[-1.0,0,-0.1],rShin:[1.2,0,0],lThigh:[-0.6,0,0.1],lShin:[1.4,0,0],rArm:[0.7,0,0],lArm:[0.7,0,0.2]}),
 ko:ov(S0,[0,-0.74,-0.15],{hips:[-1.5,0,0],spine:[0,0,0],chest:[0,0,0],head:[0.2,0,0],rArm:[0.1,0,-0.9],lArm:[0.1,0,0.9],rFore:[0.2,0,0],lFore:[0.2,0,0],rThigh:[0,0,-0.1],lThigh:[0,0,0.1],rShin:[0.1,0,0],lShin:[0.1,0,0]}),
 win:ov(S0,[0,-0.02,0],{rArm:[2.7,0,-0.5],lArm:[2.7,0,0.5],rFore:[0.3,0,0],lFore:[0.3,0,0],rThigh:[-0.1,0,-0.12],lThigh:[0.0,0,0.12],rShin:[0.1,0,0],lShin:[0.1,0,0],head:[-0.2,0,0],chest:[-0.1,0,0],spine:[0,0,0]})
};
const ATK={
 p1:{w:'jabW',k:'jab'},p2:{w:'crossW',k:'cross'},p3:{w:'hookW',k:'hook'},k1:{w:'kickW',k:'kick'},
 charge:{w:'chargeW',k:'thrust'},rise:{w:'chargeW',k:'rise'}};
function attackPose(id,s,st,en,dur){
 const a=ATK[id],B=stance(s),W=POSES[a.w],K=POSES[a.k];
 if(s<st)return mixPose(B,W,smooth(s/st));
 const mid=st+(en-st)*0.35;
 if(s<mid)return mixPose(W,K,smooth((s-st)/(mid-st)));
 if(s<en)return K;
 return mixPose(K,B,smooth((s-en)/(dur-en)));}
function moveClip(t,vf,vs){
 const sp=Math.hypot(vf,vs),amp=clamp(sp/2.6,0,1),ph=t*2*Math.PI*(1.1+0.7*amp)*(vf<-0.1?-1:1);
 const s=Math.sin(ph),c=Math.cos(ph),B=stance(t);
 const r=B.rot;
 r.rThigh=[r.rThigh[0]-0.38*amp*s,0,r.rThigh[2]];r.lThigh=[r.lThigh[0]+0.38*amp*s,0,r.lThigh[2]];
 r.rShin=[r.rShin[0]+0.5*amp*Math.max(0,Math.sin(ph-0.6)),0,0];r.lShin=[r.lShin[0]+0.5*amp*Math.max(0,Math.sin(ph+Math.PI-0.6)),0,0];
 r.hips=[0.05,0.12*clamp(vs/2.6,-1,1),0.04*Math.sin(ph)*amp];
 B.root=[0.015*Math.sin(ph)*amp,B.root[1]+0.025*amp*Math.sin(2*ph+0.9),0];
 return B;}
function jumpPose(vy){return mixPose(stance(0),POSES.jump,smooth(1-Math.abs(vy)/7));}

// ===== CLOUD BODY BUILDER (generic, driven by archetype) =====
const SEG=[
 ['hips',[0,.93,0],[0,1.05,0],.14,.14,.06,'torso'],['spine',[0,1.06,0],[0,1.24,0],.135,.135,.07,'torso'],['chest',[0,1.24,0],[0,1.42,0],.152,.152,.10,'torso'],
 ['neck',[0,1.505,0],[0,1.565,0],.052,.05,.006,'neck'],
 ['lArm',[-.205,1.42,0],[-.265,1.157,0],.055,.05,.035,'limb'],['rArm',[.205,1.42,0],[.265,1.157,0],.055,.05,.035,'limb'],
 ['lFore',[-.265,1.157,0],[-.32,.915,0],.046,.04,.03,'limb'],['rFore',[.265,1.157,0],[.32,.915,0],.046,.04,.03,'limb'],
 ['lThigh',[-.095,.97,0],[-.095,.55,0],.08,.065,.065,'limb'],['rThigh',[.095,.97,0],[.095,.55,0],.08,.065,.065,'limb'],
 ['lShin',[-.095,.55,0],[-.095,.15,0],.06,.045,.05,'limb'],['rShin',[.095,.55,0],[.095,.15,0],.06,.045,.05,'limb'],
 ['lFoot',[-.095,.07,-.04],[-.095,.07,.17],.055,.05,.03,'foot'],['rFoot',[.095,.07,-.04],[.095,.07,.17],.055,.05,.03,'foot']];
const SPH=[
 ['head',[0,1.605,0],.105,[.92,1.02,.95],.03,'head'],['lArm',[-.205,1.42,0],.085,[.9,.82,.9],.012,'limb'],['rArm',[.205,1.42,0],.085,[.9,.82,.9],.012,'limb'],
 ['lHand',[-.328,.874,.005],.05,[.78,1.05,.85],.012,'hand'],['rHand',[.328,.874,.005],.05,[.78,1.05,.85],.012,'hand']];
const PARENT_OF={};BONES.forEach(b=>{if(b.parent>=0)PARENT_OF[b.name]=BONES[b.parent].name;});
const cone=(bone,a,b,r,col,sh)=>({t:'cap',bone,a,b,r0:r,r1:0.004,col,sh});
const ball=(bone,c,r,sc,col,sh,kind)=>({t:'sph',bone,c,r,sc:sc||[1,1,1],col,sh,kind:kind||0});
function mirror(f){return [f(1),f(-1)];}
const ARCH={
 op:{name:'OPERATOR',S:1,W:1,hp:100,spd:1,dmg:1,reach:1,aggr:.5,ideal:1.5,pw:['plasma','nova'],rm:{},
  pal:{fill:[.16,.44,.47],fill2:[.12,.3,.34],edge:[.15,1.15,.95],acc:[1.2,.88,.16],eye:[.2,1.4,1.2]},fx:{shim:.012,jit:0,rise:0},hot:[1.4,1.2,.5],
  ex:()=>[ball('head',[0,1.64,0],.125,[1.05,.75,1.1],'acc',.04),{t:'cap',bone:'chest',a:[0,1.12,-.155],b:[0,1.38,-.155],r0:.1,r1:.1,col:'edge',sh:.02},
   {t:'cap',bone:'gun',a:[.322,.859,.07],b:[.322,.84,.4],r0:.035,r1:.03,col:'edge',sh:.012,kind:1},{t:'cap',bone:'gun',a:[.322,.84,.4],b:[.322,.8,.62],r0:.016,r1:.016,col:'acc',sh:.006,kind:1},
   {t:'cap',bone:'gun',a:[.3,.9,0],b:[.3,.95,-.25],r0:.022,r1:.022,col:'edge',sh:.006,kind:1}]},
 ember:{name:'EMBER BRUTE',S:1.22,W:1.3,hp:130,spd:.85,dmg:1.25,reach:1.1,aggr:.65,ideal:1.6,pw:['fire','pillar'],rm:{torso:1.15,limb:1.2,hand:1.5},
  pal:{fill:[.55,.12,.04],fill2:[.9,.3,.05],edge:[1.5,.8,.1],acc:[1.6,1.1,.3],eye:[1.8,1.6,.5]},fx:{shim:.02,jit:0,rise:1},hot:[1.6,.8,.2],
  ex:()=>[...mirror(s=>cone('head',[s*.07,1.66,0],[s*.24,1.93,.04],.045,'acc',.012)),...mirror(s=>ball(s>0?'rArm':'lArm',[s*.215,1.46,0],.15,[1,.8,1],'fill2',.03)),
   ball('chest',[0,1.34,.1],.07,[1,1,1],'acc',.008),{t:'aura',col:'acc',sh:.12},{t:'aura',col:'fill2',sh:.08}]},
 frost:{name:'FROST WRAITH',S:1.12,W:.78,hp:90,spd:1.05,dmg:.9,reach:1.15,aggr:.5,ideal:3.0,pw:['shards','zero'],rm:{torso:.8,limb:.8},
  pal:{fill:[.35,.62,.75],fill2:[.7,.9,1],edge:[.7,1.5,1.7],acc:[1.5,1.7,1.9],eye:[1.8,1.8,2]},fx:{shim:.006,jit:0,rise:.4},hot:[.7,1.5,1.8],
  ex:()=>[...mirror(s=>cone(s>0?'rArm':'lArm',[s*.22,1.45,0],[s*.6,1.9,-.05],.05,'acc',.014)),
