 plasma:{n:'PLASMA SURGE',cost:25,dur:.75,fx:.36,anim:'charge'},nova:{n:'NOVA BURST',cost:50,dur:.85,fx:.3,anim:'rise'},
 fire:{n:'FIREBALL',cost:25,dur:.8,fx:.4,anim:'charge'},pillar:{n:'INFERNO PILLAR',cost:50,dur:.95,fx:.35,anim:'rise'},
