function buildCloud(key,N){
 const A=ARCH[key],pal=A.pal,rm=A.rm,S=[];
 const g=(grp)=>rm[grp]||1;
 SEG.forEach(s=>S.push({t:'cap',bone:s[0],a:s[1],b:s[2],r0:s[3]*g(s[6]),r1:s[4]*g(s[6]),sh:s[5],col:'fill',edgeBand:.07,blend:s[0] in PARENT_OF&&s[6]!=='torso'?PARENT_OF[s[0]]:null}));
 SPH.forEach(s=>S.push({t:'sph',bone:s[0],c:s[1],r:s[2]*g(s[5]),sc:s[3],sh:s[4],col:'fill',head:s[0]==='head',spark:.02}));
 A.ex().forEach(e=>S.push(e));
 let tot=0;S.forEach(s=>tot+=s.sh);
 const pos=new Float32Array(N*3),col=new Float32Array(N*3),skin=new Float32Array(N*4),ex=new Float32Array(N*3);
 let k=0;
 const fillC=pal.fill,f2=pal.fill2;
 for(const s of S){
  let cnt=Math.round(N*s.sh/tot);if(k+cnt>N)cnt=N-k;if(cnt<=0)continue;
  const bi=s.t==='aura'?BIDX.hips:BIDX[s.bone],rq=REST_Q[bi],bp=BONES[bi].pos,kind=s.t==='aura'?3:(s.kind||0);
  const b2=s.blend?BIDX[s.blend]:bi;
  let ax,ux,uy,uz,wx,wy,wz,L=0;
  if(s.t==='cap'){const d=V3.sub(s.b,s.a);L=V3.len(d)||1;ax=V3.scale(d,1/L);
   let h=Math.abs(ax[1])>.9?[1,0,0]:[0,1,0];const u=V3.norm(V3.cross(ax,h)),w=V3.cross(ax,u);[ux,uy,uz]=u;[wx,wy,wz]=w;}
  const colE=s.col&&pal[s.col]?pal[s.col]:null;
  for(let i=0;i<cnt&&k<N;i++,k++){
   let px,py,pz,edge=false,t=.5;
   if(s.t==='cap'){t=Math.random();const th=Math.random()*6.2832,r=s.r0+(s.r1-s.r0)*t,c=Math.cos(th),sn=Math.sin(th);
    px=s.a[0]+ax[0]*L*t+(ux*c+wx*sn)*r;py=s.a[1]+ax[1]*L*t+(uy*c+wy*sn)*r;pz=s.a[2]+ax[2]*L*t+(uz*c+wz*sn)*r;
    const eb=s.edgeBand||0;edge=(eb&&(t<eb||t>1-eb))||Math.random()<.03;}
   else if(s.t==='sph'){let vx,vy,vz,l;do{vx=rnd(-1,1);vy=rnd(-1,1);vz=rnd(-1,1);l=vx*vx+vy*vy+vz*vz;}while(l>1||l<1e-4);l=Math.sqrt(l);vx/=l;vy/=l;vz/=l;
    px=s.c[0]+vx*s.r*s.sc[0];py=s.c[1]+vy*s.r*s.sc[1];pz=s.c[2]+vz*s.r*s.sc[2];
    edge=Math.random()<(s.spark||.02);if(s.head&&vz>.55&&py>1.585&&py<1.64)edge=true;}
   else if(s.t==='ring'){const th=Math.random()*6.2832;px=s.c[0]+Math.cos(th)*s.r+rnd(-.012,.012);py=s.c[1]+rnd(-.012,.012);pz=s.c[2]+Math.sin(th)*s.r;edge=true;}
   else{const th=Math.random()*6.2832,rr=.1+Math.random()*.22;px=Math.cos(th)*rr;py=rnd(.15,1.0);pz=Math.sin(th)*rr;edge=true;}
   const lc=Q.rotVecConj(rq,[px-bp[0],py-bp[1],pz-bp[2]]);
   pos[k*3]=lc[0];pos[k*3+1]=lc[1];pos[k*3+2]=lc[2];
   let w1=0;if(s.blend&&t<.18)w1=.5*(1-t/.18);
   skin[k*4]=bi;skin[k*4+1]=1-w1;skin[k*4+2]=b2;skin[k*4+3]=w1;
   let c=edge?(s.head&&px*0===0&&pz>0&&k%3===0?pal.eye:(colE&&s.t!=='cap'?colE:pal.edge)):(colE&&s.col!=='fill'?colE:null);
   if(!c){const m=Math.random()*(Math.sin(px*9+py*7)*.5+.5);c=[fillC[0]+(f2[0]-fillC[0])*m,fillC[1]+(f2[1]-fillC[1])*m,fillC[2]+(f2[2]-fillC[2])*m];}
   const br=.85+Math.random()*.45;col[k*3]=c[0]*br;col[k*3+1]=c[1]*br;col[k*3+2]=c[2]*br;
   ex[k*3]=Math.random();ex[k*3+1]=edge||kind===3?1:0;ex[k*3+2]=kind;
  }}
 while(k<N){const s=S[2],bi=BIDX.chest,rq=REST_Q[bi],bp=BONES[bi].pos;const th=Math.random()*6.2832,t=Math.random();
  const lc=Q.rotVecConj(rq,[Math.cos(th)*.15,1.24+.18*t-bp[1],Math.sin(th)*.15]);
  pos[k*3]=lc[0];pos[k*3+1]=lc[1];pos[k*3+2]=lc[2];skin[k*4]=bi;skin[k*4+1]=1;skin[k*4+2]=bi;skin[k*4+3]=0;
  col[k*3]=fillC[0];col[k*3+1]=fillC[1];col[k*3+2]=fillC[2];ex[k*3]=Math.random();k++;}
 return {pos,col,skin,ex,count:N};
}

// ===== SVG VECTOR PARTICLE ENGINE =====
const NSVG='http://www.w3.org/2000/svg';const $=id=>document.getElementById(id);
function el(tag,attrs,parent){const n=document.createElementNS(NSVG,tag);if(attrs)for(const k in attrs){if(k==='text')n.textContent=attrs[k];else n.setAttribute(k,attrs[k]);}if(parent)parent.appendChild(n);return n;}
// HDR color -> 4-level/channel palette (64 css colors)
const PAL=[];(function(){for(let r=0;r<4;r++)for(let g=0;g<4;g++)for(let b=0;b<4;b++){const f=v=>Math.min(255,Math.round(v*88));PAL.push('rgb('+f(r)+','+f(g)+','+f(b)+')');}})();
function quantC(r,g,b){let ri=(r*2.4)|0,gi=(g*2.4)|0,bi=(b*2.4)|0;if(ri<0)ri=0;if(gi<0)gi=0;if(bi<0)bi=0;if(ri>3)ri=3;if(gi>3)gi=3;if(bi>3)bi=3;return ri*16+gi*4+bi;}
function cssC(r,g,b){if(Array.isArray(r)){g=r[1];b=r[2];r=r[0];}const f=v=>Math.round(Math.min(255,Math.max(0,v*150)));return 'rgb('+f(r)+','+f(g)+','+f(b)+')';}
// dot size classes (px diameter)
const SZ=[1.5,2.2,3.2,4.8,7.2,11];
function BucketRenderer(parent){
 this.g=el('g',{'class':'bucketG'},parent);
 this.arr=new Array(384).fill(null);this.nodes=new Array(384).fill(null);this.lastW=new Array(384).fill(-1);
 this.used=[];this.prev=[];
}
BucketRenderer.prototype.begin=function(){const u=this.used;for(let i=0;i<u.length;i++)this.arr[u[i]]=null;u.length=0;};
BucketRenderer.prototype.push=function(x,y,ci,s){
 if(s<.9)return;const si=s<1.85?0:s<2.7?1:s<4?2:s<6?3:s<9.1?4:5;
 const idx=ci*6+si;let a=this.arr[idx];
 if(!a){a=this.arr[idx]=[];this.used.push(idx);}
 a.push('M'+x+' '+y+'l.01 0');};
BucketRenderer.prototype.flush=function(){
 for(let i=0;i<this.prev.length;i++){const idx=this.prev[i],a=this.arr[idx];if((!a||a.length===0)&&this.nodes[idx])this.nodes[idx].setAttribute('d','');}
 const u=this.used;
 for(let i=0;i<u.length;i++){const idx=u[i],a=this.arr[idx];if(!a.length)continue;
  let n=this.nodes[idx];
  if(!n){n=this.nodes[idx]=el('path',{'class':'bucket'},this.g);n.setAttribute('stroke',PAL[(idx/6)|0]);}
  n.setAttribute('d',a.join(''));
  const w=SZ[idx%6];if(w!==this.lastW[idx]){n.setAttribute('stroke-width',w);this.lastW[idx]=w;}
  DRAWCALLS++;}
 this.prev=u.slice();};
function World(){this.entities=[];this.systems=[];this.t=0;}
World.prototype.create=function(name){const e={id:this.entities.length,name:name,comps:{},add:function(c){this.comps[c.type]=c;return this;},get:function(t){return this.comps[t];}};this.entities.push(e);return e;};
World.prototype.addSystem=function(name,fn){this.systems.push({name:name,update:fn});};
function C(type,o){this.type=type;if(o)Object.assign(this,o);}

