// ===== CPU PARTICLE FX =====
const FXP=[];const FX_CAP=1400;
function emit(p,v,c,life,size,drag,grav){if(FXP.length>=FX_CAP)FXP.shift();
 FXP.push({p:[p[0],p[1],p[2]],v:v,ci:quantC(c[0],c[1],c[2]),life:life,max:life,s:size||2,drag:drag===undefined?2:drag,g:grav||0});}
function burst(p,n,spd,c1,c2,life,size,grav){for(let i=0;i<n;i++){const d=V3.norm([Math.random()-.5,Math.random()-.5,Math.random()-.5]),m=Math.random(),sp=spd*(.3+Math.random()*.7);
 emit(p,V3.scale(d,sp),[c1[0]+(c2[0]-c1[0])*m,c1[1]+(c2[1]-c1[1])*m,c1[2]+(c2[2]-c1[2])*m],life*(.5+Math.random()*.5),size,2,grav);}}
function stepFX(dt){for(let i=FXP.length-1;i>=0;i--){const f=FXP[i];f.life-=dt;if(f.life<=0){FXP.splice(i,1);continue;}
 f.v[1]-=f.g*dt;const k=Math.max(0,1-f.drag*dt);f.v[0]*=k;f.v[1]*=k;f.v[2]*=k;f.p[0]+=f.v[0]*dt;f.p[1]+=f.v[1]*dt;f.p[2]+=f.v[2]*dt;if(f.p[1]<.02){f.p[1]=.02;f.v[1]*=-.3;}}}

