const G_=24,JUMPV=8.4;
const M={mode:'FIGHT',twoP:false,round:1,wins:[0,0],timer:99,state:'intro',st:0,opp:1,p1:0,msg:'',msgT:0,stage:0,over:null,ladder:1,arena:11.5};
const MV={
 p1:{st:.07,en:.17,dur:.28,dmg:4,reach:1.35,kb:1.5,stun:.2,lunge:1.4,anim:'p1'},
 p2:{st:.08,en:.18,dur:.30,dmg:5,reach:1.45,kb:1.9,stun:.24,lunge:1.7,anim:'p2'},
