let statusMsg=function(){};
function mkInput(){return {mx:0,mz:0,block:false,press:{punch:0,kick:0,p1:0,p2:0,jump:0}};}
function makeFighter(w,name,key,slot){
 const e=w.create(name);
 e.add(new C('Transform',{pos:[0,0,0],yaw:0}));
 e.add(new C('Rig',{mats:new Float32Array(NB*16),pos:new Float32Array(NB*3)}));
 e.add(new C('Fighter',{slot:slot,key:key,A:ARCH[key],S:ARCH[key].S,hp:100,max:100,en:30,state:'free',st:0,mv:null,mdef:null,hitDone:false,spawned:false,
  vx:0,vz:0,y:0,vy:0,air:false,block:false,stun:0,freeze:0,slow:0,combo:0,comboT:0,chainIdx:0,chainT:0,queue:null,buf:{punch:0,kick:0,p1:0,p2:0,jump:0},
  pulse:0,burst:0,dis:0,flash:0,hot:new Float32Array(NB),hotT:new Float32Array(NB),in:mkInput(),ai:{t:0,mode:'idle',lvl:.5,mt:0},ctl:'ai',lastHit:-9,fall:0}));
 e.add(new C('Animator',{t:0,blendFrom:null,blendT:1,prev:'',last:null,pose:null}));
 e.add(new C('Cloud'));
 return e;}
function setArch(e,key){const F=e.get('Fighter');F.key=key;F.A=ARCH[key];F.S=F.A.S;F.max=F.A.hp;F.hp=F.max;ensureCloud(key);}
const HOT={p1:['rHand','rFore'],p2:['lHand','lFore'],p3:['rHand','rFore','rArm'],k1:['rFoot','rShin','rThigh']};
function startAtk(f,id){f.state='atk';f.st=0;f.mv=id;f.hitDone=false;f.spawned=false;f.queue=null;
 if(id==='pw1'||id==='pw2'){const pid=f.A.pw[id==='pw1'?0:1],p=PW[pid];f.en-=p.cost;f.mdef={pw:pid,st:p.fx,en:p.fx+.18,dur:p.dur,anim:p.anim};}
 else f.mdef=MV[id];}
function dist2(a,b){return Math.hypot(a.pos[0]-b.pos[0],a.pos[2]-b.pos[2]);}
function faceDir(T){return [Math.sin(T.yaw),Math.cos(T.yaw)];}
function inRange(fT,f,oT,o,reach){
 const d=dist2(fT,oT),dx=oT.pos[0]-fT.pos[0],dz=oT.pos[2]-fT.pos[2],fd=faceDir(fT);
 if(d>reach*f.S+.3*o.S)return false;
 const cs=(dx*fd[0]+dz*fd[1])/(d||1);if(cs<.45)return false;
 if(o.y>1.0&&f.y<.3)return false;return true;}
function dmgFx(p,att,heavy){const h=att.A.hot;burst(p,heavy?40:18,heavy?9:6,[1.5,1.4,1.2],h,heavy?.45:.3,3,6);}
function applyHit(aT,a,dT,d,o){
 if(d.state==='ko'||d.state==='down'||M.state!=='fight')return false;
 let dmg=o.dmg,kb=o.kb,stun=o.stun;
 const hp=[dT.pos[0],dT.pos[1]+(1.1*d.S)+d.y,dT.pos[2]];
 let dx=dT.pos[0]-aT.pos[0],dz=dT.pos[2]-aT.pos[2];const l=Math.hypot(dx,dz)||1;dx/=l;dz/=l;
 const blocked=d.block&&d.state==='free'&&!d.air&&!o.launch;
 if(blocked){dmg*=.12;kb*=.35;stun=.14;burst(hp,16,5,[.3,.8,1.6],[.6,1.2,2],.3,3,0);d.en=Math.min(100,d.en+2);}
 else{dmgFx(hp,a,o.heavy);d.flash=1;d.burst=Math.max(d.burst,o.heavy?.6:.25);
  d.en=Math.min(100,d.en+4);a.en=Math.min(100,a.en+(o.pw?3:6));a.combo++;a.comboT=1.4;
  if(o.freeze){d.freeze=o.freeze;}if(o.slow)d.slow=o.slow;
  if(o.launch){d.vy=o.launch;d.air=true;stun=2;}
  d.state='hit';d.st=0;d.stun=o.freeze?Math.max(stun,o.freeze):stun;d.mv=null;d.queue=null;}
 d.hp=Math.max(0,d.hp-dmg);d.vx=dx*kb;d.vz=dz*kb;
 HITSTOP=Math.max(HITSTOP,blocked?.03:.04+dmg*.004);CAM.shake=Math.max(CAM.shake,blocked?.04:.08+dmg*.006);
 if(d.hp<=0&&M.state==='fight'){d.state='ko';d.st=0;d.vx=dx*4;d.vz=dz*4;d.vy=4;d.air=true;a.state==='atk'&&(a.state='free');a.hit0=0;endRound(a,d);}
 return !blocked;}
function sink(e){return {T:e.get('Transform'),F:e.get('Fighter')};}
// ----- power implementations -----
function chestPos(T,F,fwd){const f=faceDir(T);return [T.pos[0]+f[0]*(fwd||.5)*F.S,T.pos[1]+(1.25*F.S)+F.y,T.pos[2]+f[1]*(fwd||.5)*F.S];}
function aimDir(T,oT,o,F){const c=chestPos(T,F,.5),tg=[oT.pos[0],oT.pos[1]+1.1*o.S+o.y*.6,oT.pos[2]];return V3.norm(V3.sub(tg,c));}
function spawnProj(a,aT,o,oT,p){const c=chestPos(aT,a,p.fwd||.6);if(p.up)c[1]+=p.up;
 const d=p.dir||aimDir(aT,oT,o,a);PROJ.push(Object.assign({own:a,tgt:o,tT:oT,aT:aT,pos:c,vel:V3.scale(d,p.spd),life:p.life||2.2,t:0,home:0,grav:0,stun:.26,kb:3,launch:0,freeze:0,slow:0,n:4000,tail:1},p));}
function castPower(e,oe,pid){
 const a=e.get('Fighter'),aT=e.get('Transform'),o=oe.get('Fighter'),oT=oe.get('Transform');
 a.burst=Math.max(a.burst,.4);
 const A=a.A;
 switch(pid){
 case 'plasma':spawnProj(a,aT,o,oT,{spd:13,r:.34,dmg:12,c1:[.2,1,1.3],c2:[1.5,1,.2],kb:4,stun:.3,n:5000,heavy:1});break;
 case 'fire':spawnProj(a,aT,o,oT,{spd:8.5,r:.55,dmg:15,c1:[1.5,.35,.05],c2:[1.6,1.3,.3],kb:5,stun:.34,n:6000,tail:1.3,heavy:1});break;
 case 'shards':{const b=aimDir(aT,oT,o,a);for(let i=-1;i<=1;i++){const an=i*.2,c=Math.cos(an),s=Math.sin(an);
   spawnProj(a,aT,o,oT,{dir:V3.norm([b[0]*c-b[2]*s,b[1],b[0]*s+b[2]*c]),spd:16,r:.17,dmg:5,c1:[.5,1.2,1.7],c2:[1.5,1.7,1.9],kb:2,stun:.22,slow:1.6,n:1800,tail:1.5});}break;}
 case 'orb':spawnProj(a,aT,o,oT,{spd:4.6,r:.48,dmg:13,c1:[.8,.1,1.4],c2:[1.7,.6,1.9],kb:3,stun:.5,home:2.6,life:4,n:6000,heavy:1});break;
 case 'boulder':spawnProj(a,aT,o,oT,{spd:9.5,r:.62,dmg:17,c1:[.4,.35,.25],c2:[.5,1.2,.4],kb:6.5,stun:.45,grav:9,up:1.2,dir:V3.norm([aimDir(aT,oT,o,a)[0],.55,aimDir(aT,oT,o,a)[2]]),n:5000,tail:.5,heavy:1});break;
 case 'nova':GFX.push({type:'nova',a,aT,o,oT,t:0,dur:.7,done:false,pos:[aT.pos[0],aT.pos[1]+(.9*a.S),aT.pos[2]],r:0});burst(aT.pos,90,10,[1.2,1,.3],A.hot,.9,3.5,0);break;
 case 'pillar':GFX.push({type:'pillar',a,aT,o,oT,t:0,dur:1.3,done:false,pos:[oT.pos[0],0,oT.pos[2]]});break;
 case 'zero':GFX.push({type:'zero',a,aT,o,oT,t:0,dur:.9,done:false,pos:[aT.pos[0],0,aT.pos[2]]});break;
 case 'horizon':GFX.push({type:'horizon',a,aT,o,oT,t:0,dur:1.6,done:false,pos:[oT.pos[0],.9,oT.pos[2]]});break;
 case 'quake':GFX.push({type:'quake',a,aT,o,oT,t:0,dur:1.3,done:false,pos:[aT.pos[0],0,aT.pos[2]]});break;
 case 'bolt':{const c=chestPos(aT,a,.5),tg=[oT.pos[0],oT.pos[1]+1.2*o.S+o.y*.5,oT.pos[2]];bolt(c,tg);
   if(!(o.y>1.3))applyHit(aT,a,oT,o,{dmg:11*A.dmg,kb:2,stun:.35,pw:1});GFX.push({type:'flash',pos:tg,t:0,dur:.3});break;}
 case 'dash':{const dx=oT.pos[0]-aT.pos[0],dz=oT.pos[2]-aT.pos[2],l=Math.hypot(dx,dz)||1;const from=chestPos(aT,a,0);
   const np=[oT.pos[0]+dx/l*1.4,0,oT.pos[2]+dz/l*1.4];
   bolt(from,[np[0],from[1],np[2]]);aT.pos[0]=np[0];aT.pos[2]=np[2];aT.yaw=Math.atan2(-dx,-dz);
   burst(from,60,8,[1.7,1.6,.5],[.5,.9,2],.5,3,0);
   applyHit(aT,a,oT,o,{dmg:15*A.dmg,kb:4,stun:.4,pw:1,heavy:1});break;}
 }}
function bolt(a,b){const n=26;let prev=a;for(let i=1;i<=n;i++){const t=i/n,j=(1-Math.abs(t*2-1)*.2)*.45;
 const p=[a[0]+(b[0]-a[0])*t+rnd(-j,j),a[1]+(b[1]-a[1])*t+rnd(-j,j),a[2]+(b[2]-a[2])*t+rnd(-j,j)];
 for(let k=0;k<8;k++){const q=V3.lerp(prev,p,k/8);emit(q,[rnd(-1,1),rnd(-1,1),rnd(-1,1)],[1.6+Math.random()*.2,1.6,.6+Math.random()],.22+Math.random()*.2,3.4,3,0);}prev=p;}}
function updateProj(dt){
 for(let i=PROJ.length-1;i>=0;i--){const p=PROJ[i];p.t+=dt;p.life-=dt;
  if(p.home){const tg=[p.tT.pos[0],p.tT.pos[1]+1.1*p.tgt.S,p.tT.pos[2]],d=V3.norm(V3.sub(tg,p.pos)),sp=V3.len(p.vel);const k=Math.min(1,p.home*dt);
   p.vel=V3.scale(V3.norm(V3.lerp(V3.norm(p.vel),d,k)),sp);}
  p.vel[1]-=p.grav*dt;p.pos[0]+=p.vel[0]*dt;p.pos[1]+=p.vel[1]*dt;p.pos[2]+=p.vel[2]*dt;
  emit(p.pos,[rnd(-1,1),rnd(-1,1),rnd(-1,1)],V3.lerp(p.c1,p.c2,Math.random()),.35,2.4,3,0);
  const o=p.tgt,oT=p.tT;const dh=Math.hypot(p.pos[0]-oT.pos[0],p.pos[2]-oT.pos[2]);
  const hitB=dh<p.r+.45*o.S&&p.pos[1]>oT.pos[1]+o.y-.2&&p.pos[1]<o.y+1.9*o.S;
  if(hitB&&M.state==='fight'){applyHit(p.aT,p.own,oT,o,{dmg:p.dmg*p.own.A.dmg,kb:p.kb,stun:p.stun,launch:p.launch,freeze:p.freeze,slow:p.slow,pw:1,heavy:p.heavy});
   burst(p.pos,p.heavy?70:30,9,p.c1,p.c2,.6,3.5,2);GFX.push({type:'flash',pos:[p.pos[0],p.pos[1],p.pos[2]],t:0,dur:.35,c1:p.c1,c2:p.c2});PROJ.splice(i,1);continue;}
  if(p.life<=0||p.pos[1]<.05||Math.hypot(p.pos[0],p.pos[2])>40){burst(p.pos,20,5,p.c1,p.c2,.4,3,2);PROJ.splice(i,1);}}}
function updateGFX(dt){
 for(let i=GFX.length-1;i>=0;i--){const g=GFX[i];g.t+=dt;
  if(g.type==='nova'){g.r=g.t/.5*3.6;if(!g.done&&g.t>.05){g.done=true;
    if(dist2(g.aT,g.oT)<3.8*g.a.S+.3&&g.o.state!=='ko')applyHit(g.aT,g.a,g.oT,g.o,{dmg:22*g.a.A.dmg,kb:6,stun:.5,launch:6.2,pw:1,heavy:1});}}
  else if(g.type==='pillar'){if(!g.done&&g.t>.7){g.done=true;burst([g.pos[0],.3,g.pos[2]],80,9,[1.5,.5,.1],[1.6,1.4,.3],.8,3.5,-3);
    if(Math.hypot(g.oT.pos[0]-g.pos[0],g.oT.pos[2]-g.pos[2])<1.5&&g.o.y<1.3)applyHit(g.aT,g.a,g.oT,g.o,{dmg:22*g.a.A.dmg,kb:2,stun:.5,launch:7,pw:1,heavy:1});}}
  else if(g.type==='zero'){g.r=g.t/.6*4.4;if(!g.done&&g.r>dist2(g.aT,g.oT)-.3){g.done=true;
    if(g.o.state!=='ko'&&g.o.y<1.5)applyHit(g.aT,g.a,g.oT,g.o,{dmg:13*g.a.A.dmg,kb:3,stun:.6,freeze:1.3,pw:1,heavy:1});}}
  else if(g.type==='horizon'){const dx=g.pos[0]-g.oT.pos[0],dz=g.pos[2]-g.oT.pos[2],d=Math.hypot(dx,dz);
    if(g.t<1.05&&g.o.state!=='ko'&&d>.4&&d<5){const k=Math.min(1,dt*6)*Math.min(4,d);g.oT.pos[0]+=dx/d*k*dt*2.2;g.oT.pos[2]+=dz/d*k*dt*2.2;}
    if(!g.done&&g.t>1.1){g.done=true;burst(g.pos,110,11,[1.7,.5,1.9],[.5,.1,1],.9,3.5,0);
     if(d<2.4&&g.o.state!=='ko')applyHit(g.aT,g.a,g.oT,g.o,{dmg:19*g.a.A.dmg,kb:3,stun:.5,launch:5.5,pw:1,heavy:1});}}
  else if(g.type==='quake'){const R=g.t*7.5;g.r=R;if(!g.done&&Math.abs(R-dist2(g.aT,g.oT))<.7){if(g.o.y<.5&&g.o.state!=='ko'){g.done=true;
    applyHit(g.aT,g.a,g.oT,g.o,{dmg:21*g.a.A.dmg,kb:3,stun:.5,launch:4.8,pw:1,heavy:1});}}
   if(Math.random()<.9){const an=Math.random()*6.28;emit([g.pos[0]+Math.cos(an)*R,.1,g.pos[2]+Math.sin(an)*R],[rnd(-1,1),rnd(2,5),rnd(-1,1)],[.6,.55,.4],.6,3.2,1,9);}}
  if(g.t>=g.dur)GFX.splice(i,1);}}
// ----- fighter update -----
function targetHot(F){F.hotT.fill(0);
 if(F.state==='atk'&&F.mdef){const m=F.mdef,id=F.mv;let h=0;if(F.st<m.st)h=.55*F.st/m.st;else if(F.st<m.en*1.5)h=1;else h=Math.max(0,1-(F.st-m.en*1.5)/.15);
  const bones=m.pw?['lHand','rHand','lFore','rFore']:HOT[id];for(const b of bones)F.hotT[BIDX[b]]=h;
  F.pulse+=((m.pw?(F.st<m.en+.1?1:0):.3*h)-F.pulse)*.2;}
 else F.pulse+=(0-F.pulse)*.12;}
function updateFighter(e,oe,dt,real){
 const T=e.get('Transform'),F=e.get('Fighter'),oT=oe.get('Transform'),O=oe.get('Fighter');
 for(const k in F.buf){if(F.in.press[k]){F.buf[k]=.16;F.in.press[k]=0;}if(F.buf[k]>0)F.buf[k]-=dt;}
 F.comboT-=dt;if(F.comboT<=0)F.combo=0;F.chainT-=dt;F.flash=Math.max(0,F.flash-dt*5);F.burst=Math.max(0,F.burst-dt*2.6);
 if(F.freeze>0)F.freeze-=dt;if(F.slow>0)F.slow-=dt;
 F.en=Math.min(100,F.en+(real?2.2:0)*dt);
 F.st+=dt;
 const dx=oT.pos[0]-T.pos[0],dz=oT.pos[2]-T.pos[2],d=Math.hypot(dx,dz)||1;
 let yawT=Math.atan2(dx,dz);
 F.block=false;
 if(F.state==='free'){
  const sp=F.A.spd*2.7*(F.slow>0?.5:1);
  F.block=F.in.block&&!F.air;
  const spd=F.block?sp*.35:sp;
  const mx=F.in.mx,mz=F.in.mz,m=Math.min(1,Math.hypot(mx,mz));
  if(!F.air){const k=Math.min(1,dt*10);F.vx+=((m>.05?mx/(m>0?Math.hypot(mx,mz):1)*spd*m:0)-F.vx)*k;F.vz+=((m>.05?mz/Math.hypot(mx,mz)*spd*m:0)-F.vz)*k;}
  if(F.buf.jump>0&&!F.air&&!F.block){F.vy=JUMPV*(.92+.08*F.A.spd);F.air=true;F.buf.jump=0;}
  if(!F.block){
   if(F.buf.p1>0&&F.en>=PW[F.A.pw[0]].cost&&!F.air){F.buf.p1=0;startAtk(F,'pw1');}
   else if(F.buf.p2>0&&F.en>=PW[F.A.pw[1]].cost&&!F.air){F.buf.p2=0;startAtk(F,'pw2');}
   else if(F.buf.punch>0){F.buf.punch=0;F.chainIdx=F.chainT>0?(F.chainIdx+1)%3:0;startAtk(F,'p'+(F.chainIdx+1));}
   else if(F.buf.kick>0){F.buf.kick=0;startAtk(F,'k1');}}
 }else if(F.state==='atk'){
  const m=F.mdef;
  if(F.air){}else{F.vx*=Math.max(0,1-dt*8);F.vz*=Math.max(0,1-dt*8);}
  if(!m.pw&&F.st<m.en&&d>.85*F.S){const l=m.lunge*(1-F.st/m.en);F.vx=dx/d*l;F.vz=dz/d*l;}
  if(!m.pw&&!F.hitDone&&F.st>=m.st&&F.st<=m.en&&inRange(T,F,oT,O,m.reach)){
   F.hitDone=true;applyHit(T,F,oT,O,{dmg:m.dmg*F.A.dmg,kb:m.kb,stun:m.stun,heavy:m.dmg>=8});}
  if(m.pw&&!F.spawned&&F.st>=m.st){F.spawned=true;castPower(e,oe,m.pw);}
  if(F.buf.punch>0&&F.st>m.st&&!m.pw&&F.mv!=='k1')F.queue='punch';
  if(F.buf.kick>0&&F.st>m.en*.8&&!m.pw)F.queue='kick';
  if(F.st>=m.dur||(F.queue&&F.st>m.en+.03&&!m.pw)){
   const q=F.queue;F.state='free';F.chainT=.5;F.mv=null;
   if(q==='punch'){F.buf.punch=0;F.chainIdx=(F.chainIdx+1)%3;if(F.mdef.anim==='k1')F.chainIdx=0;startAtk(F,'p'+(F.chainIdx+1));}
   else if(q==='kick'){F.buf.kick=0;startAtk(F,'k1');}}
 }else if(F.state==='hit'){
  const k=Math.max(0,1-dt*5);if(!F.air){F.vx*=k;F.vz*=k;}
  if(F.air&&F.vy<=0&&F.y<=0){F.state='down';F.st=0;}
  else if(!F.air&&F.st>=F.stun&&F.freeze<=0){F.state='free';}
 }else if(F.state==='down'){F.vx*=Math.max(0,1-dt*6);F.vz*=Math.max(0,1-dt*6);if(F.st>.75){F.state='free';F.st=0;}}
 else if(F.state==='ko'){F.vx*=Math.max(0,1-dt*3);F.vz*=Math.max(0,1-dt*3);yawT=T.yaw;F.dis=F.st>1.2?Math.min(1,(F.st-1.2)/1.6):0;}
 else if(F.state==='win'){F.vx*=.9;F.vz*=.9;}
 T.pos[0]+=F.vx*dt;T.pos[2]+=F.vz*dt;
 if(F.air||F.y>0){F.y+=F.vy*dt;F.vy-=G_*dt;if(F.y<=0){F.y=0;F.vy=0;if(F.air&&F.state==='free'){F.air=false;burst([T.pos[0],.05,T.pos[2]],10,3,[.8,.8,.8],[.5,.5,.5],.4,2.5,-2);}
   else if(F.air){F.air=false;burst([T.pos[0],.05,T.pos[2]],24,5,[.8,.8,.8],[.5,.5,.5],.5,2.5,-2);CAM.shake=Math.max(CAM.shake,.06);}}}
 T.pos[1]=F.y;
 if(F.state!=='ko'||F.st<.3)T.yaw=lerpAngle(T.yaw,yawT,Math.min(1,dt*(F.state==='free'?12:6)));
 targetHot(F);
 for(let i=0;i<NB;i++)F.hot[i]+=(F.hotT[i]-F.hot[i])*Math.min(1,dt*18);
 if(F.dis>0&&F.state!=='ko')F.dis=Math.max(0,F.dis-dt*2);
}
function separate(aT,a,bT,b,arena){
 if(a.y>1.3||b.y>1.3)return;
 const dx=bT.pos[0]-aT.pos[0],dz=bT.pos[2]-aT.pos[2],d=Math.hypot(dx,dz)||1e-3,min=.42*(a.S+b.S)+.2;
 if(d<min){const m=(min-d)/2,nx=dx/d,nz=dz/d;aT.pos[0]-=nx*m;aT.pos[2]-=nz*m;bT.pos[0]+=nx*m;bT.pos[2]+=nz*m;}
 for(const T of [aT,bT]){const r=Math.hypot(T.pos[0],T.pos[2]);if(r>arena){T.pos[0]*=arena/r;T.pos[2]*=arena/r;}}}
// ----- AI -----
function aiThink(e,oe,dt){
 const T=e.get('Transform'),F=e.get('Fighter'),oT=oe.get('Transform'),O=oe.get('Fighter'),ai=F.ai,A=F.A,I=F.in;
 ai.t-=dt;ai.mt-=dt;
 const dx=oT.pos[0]-T.pos[0],dz=oT.pos[2]-T.pos[2],d=Math.hypot(dx,dz)||1,nx=dx/d,nz=dz/d,lv=ai.lvl;
 if(M.state!=='fight'||F.state==='ko'){I.mx=I.mz=0;I.block=false;return;}
 const pw1=PW[A.pw[0]],pw2=PW[A.pw[1]];
 if(ai.t<=0){ai.t=rnd(.1,.3)*(1.4-lv*.6);
  const threat=O.state==='atk'&&d<2.6;
  if(threat&&Math.random()<.35+.4*lv){ai.mode='block';ai.mt=.35;}
  else if(ai.mt<=0){const r=Math.random(),reach=1.55*A.reach*A.S;
   if(d<reach){ if(F.en>=pw2.cost&&r<.14*A.aggr+.08)ai.mode='pw2';else if(r<.6)ai.mode='punch';else if(r<.8)ai.mode='kick';else if(r<.9)ai.mode='retreat';else ai.mode='strafe';ai.mt=.25;}
   else if(d>A.ideal+1.2){ if(F.en>=pw1.cost&&r<.45)ai.mode='pw1';else if(r<.15&&F.en>=pw2.cost&&A.ideal>2)ai.mode='pw2';else if(r<.25)ai.mode='jump';else ai.mode='approach';ai.mt=.35;}
   else { if(A.ideal>2&&d<A.ideal-.6){ai.mode='retreat';}else ai.mode=r<.55?'approach':(r<.8?'strafe':'idle');ai.mt=.3;}
  }}
 I.mx=I.mz=0;I.block=false;
 const sx=-nz,sz=nx;
 switch(ai.mode){
  case 'approach':I.mx=nx;I.mz=nz;break;case 'retreat':I.mx=-nx;I.mz=-nz;break;
  case 'strafe':{const s=(ai.ph||(ai.ph=Math.random()<.5?1:-1));I.mx=sx*s*.9+nx*.2;I.mz=sz*s*.9+nz*.2;break;}
  case 'block':I.block=true;break;
  case 'jump':I.press.jump=1;ai.mode='approach';break;
  case 'punch':I.press.punch=1;if(Math.random()<.5*lv)ai.t=.06;ai.mode='idle';break;
  case 'kick':I.press.kick=1;ai.mode='idle';break;
  case 'pw1':I.press.p1=1;ai.mode='idle';break;case 'pw2':I.press.p2=1;ai.mode='idle';break;}
 if(ai.t<.02)ai.ph=0;}
// ----- rounds -----
function placeFighters(){const a=world.entities[0],b=world.entities[1];
 for(const [e,x,yaw] of [[a,-2.6,Math.PI/2],[b,2.6,-Math.PI/2]]){const T=e.get('Transform'),F=e.get('Fighter');
  T.pos=[x,0,0];T.yaw=yaw;F.hp=F.max;F.state='free';F.st=0;F.vx=F.vz=F.vy=F.y=0;F.air=false;F.dis=0;F.freeze=0;F.slow=0;F.combo=0;F.en=Math.max(F.en,30);F.mv=null;F.flash=0;F.burst=0;F.pulse=0;}
 PROJ.length=0;GFX.length=0;}
function startRound(){placeFighters();M.state='intro';M.st=0;M.timer=99;M.msg='ROUND '+M.round;}
function endRound(winner,loser){M.state='ko';M.st=0;M.msg='K.O.';
 const wi=winner.slot;M.wins[wi]++;winner.state='win';winner.st=0;HITSTOP=.35;CAM.shake=.25;}
function timeUp(){const a=world.entities[0].get('Fighter'),b=world.entities[1].get('Fighter');
 if(a.hp===b.hp){M.state='ko';M.st=0;M.msg='DRAW';return;}
 const w=a.hp>b.hp?a:b,l=a.hp>b.hp?b:a;l.hp=0;endRound(w,l);M.msg='TIME UP';}
function sysMatch(dt){
 if(M.mode!=='FIGHT')return;
 M.st+=dt;M.msgT-=dt;
 const a=world.entities[0].get('Fighter'),b=world.entities[1].get('Fighter');
 if(M.state==='intro'){if(M.st>1.1&&M.msg.indexOf('FIGHT')<0&&M.msg!=='FIGHT!'){M.msg='FIGHT!';}if(M.st>1.8){M.state='fight';M.st=0;M.msg='';}}
 else if(M.state==='fight'){M.timer-=dt;if(M.timer<=0)timeUp();}
 else if(M.state==='ko'){if(M.st>3){
   if(M.wins[0]>=2||M.wins[1]>=2){M.state='over';M.st=0;const p1w=M.wins[0]>=2;M.msg=p1w?'YOU WIN':(M.twoP?'PLAYER 2 WINS':'DEFEATED');}
   else{M.round++;startRound();}}}
 else if(M.state==='over'){if(M.st>3.5){const p1w=M.wins[0]>=2;M.wins=[0,0];M.round=1;
   if(p1w&&!M.twoP){M.opp=M.opp%5+1;setArch(world.entities[1],ARCH_KEYS[M.opp]);M.ladder++;}
   a.en=30;b.en=30;setArch(world.entities[0],ARCH_KEYS[M.p1]);startRound();}}
}
// ===== CLOUD MANAGER =====
const CLOUDS={};let FPS=60,DRAWCALLS=0;
function ensureCloud(key){
 const N=TIERS[tierIdx],c=CLOUDS[key];
 if(c&&(c.N===N||c.building))return;
 if(c)c.building=true;else CLOUDS[key]={building:true,count:0,N:0,fade:0,data:null};
 statusMsg('ALLOCATING '+N.toLocaleString('en-US')+' PARTICLES · '+ARCH[key].name);
 setTimeout(function(){const t0=performance.now(),d=buildCloud(key,N),cc=CLOUDS[key];
  cc.data=d;cc.count=d.count;cc.N=N;cc.building=false;cc.fade=0;
  statusMsg(ARCH[key].name+' · '+N.toLocaleString('en-US')+' PTS · '+(performance.now()-t0).toFixed(0)+' MS');},30);}
function refreshClouds(){const used={};world.entities.slice(0,2).forEach(e=>{used[e.get('Fighter').key]=1;});
 for(const k in CLOUDS)if(!used[k]&&!CLOUDS[k].building)delete CLOUDS[k];
 for(const k in used)ensureCloud(k);}
function cycleTier(d){tierIdx=(tierIdx+d+TIERS.length)%TIERS.length;refreshClouds();}
function fxQuality(){return tierIdx>=4?1:tierIdx>=3?.8:tierIdx>=2?.6:tierIdx>=1?.42:.3;}

// ===== INPUT =====
const KEY={},TOUCH={joy:{on:false,x:0,z:0},block:false,id:-1,bx:0,by:0};
const PADS=[{on:false,prev:[],ax:[0,0,0,0],btn:[],id:''},{on:false,prev:[],ax:[0,0,0,0],btn:[],id:''}];
const CAMMENU={open:false,sel:0,zoom:1,stickT:0};
let TOUCHMODE=COARSE,HELPSHOW=true,MENUSHOW=(typeof window!=='undefined'&&window.innerWidth>=900),FREEZE_ACT=false;
const SNAP=['plasma'];
function pollPads(){
 const list=navigator.getGamepads?navigator.getGamepads():[],c=[];
 for(let i=0;i<list.length;i++)if(list[i]&&list[i].connected)c.push(list[i]);
 for(let s=0;s<2;s++){const P=PADS[s],g=c[s];P.prevB=P.btn;
  if(!g){P.on=false;P.ax=[0,0,0,0];P.btn=[];continue;}
  const dz=v=>Math.abs(v)<.16?0:v;P.on=true;P.id=(g.id||'PAD').replace(/\(.*\)/,'').slice(0,20);
  P.ax=[dz(g.axes[0]||0),dz(g.axes[1]||0),dz(g.axes[2]||0),dz(g.axes[3]||0)];P.btn=g.buttons.map(b=>b.pressed||b.value>.6);}}
function pressed(P,i){return P.btn[i]&&!(P.prevB&&P.prevB[i]);}
function camBasis(){const f=[CAM.target[0]-CAM.eye[0],CAM.target[2]-CAM.eye[2]],l=Math.hypot(f[0],f[1])||1;f[0]/=l;f[1]/=l;return {f:f,r:[-f[1],f[0]]};}
function fighterInput(F,src,B){
 const w=B.r[0]*src.mx+B.f[0]*src.my,z=B.r[1]*src.mx+B.f[1]*src.my;
 const l=Math.hypot(w,z);F.in.mx=l>1?w/l:w;F.in.mz=l>1?z/l:z;F.in.block=!!src.block;
 for(const k in src.press)if(src.press[k])F.in.press[k]=1;}
const kbP1={},kbP2={};
function sysInput(dt,w){
 pollPads();const B=camBasis(),e0=w.entities[0],e1=w.entities[1],F0=e0.get('Fighter'),F1=e1.get('Fighter');
 const p0=PADS[0];
 if(p0.on){if(pressed(p0,8))toggleCamMenu();if(pressed(p0,9))togglePause();if(pressed(p0,11)&&!CAMMENU.open)nextView();
  if(CAMMENU.open){CAMMENU.stickT-=dt;
   if(pressed(p0,12)||(p0.ax[1]<-.6&&CAMMENU.stickT<=0)){camMenuMove(-1);CAMMENU.stickT=.25;}
   if(pressed(p0,13)||(p0.ax[1]>.6&&CAMMENU.stickT<=0)){camMenuMove(1);CAMMENU.stickT=.25;}
   if(pressed(p0,14)||pressed(p0,15)){CAMMENU.zoom=clamp(CAMMENU.zoom+(pressed(p0,15)?.1:-.1),.6,1.6);}
   if(pressed(p0,0))toggleCamMenu();if(pressed(p0,1))toggleCamMenu();}}
 F0.in.mx=F0.in.mz=0;F0.in.block=false;F1.in.mx=F1.in.mz=0;F1.in.block=false;
 if(CAMMENU.open){return;}
 if(CAM.view===5&&p0.on&&M.mode==='FIGHT'){CAM.yaw-=p0.ax[2]*2.2*dt;CAM.pitch=clamp(CAM.pitch+p0.ax[3]*1.6*dt,.02,1.3);}
 if(M.mode==='TPS'&&p0.on){CAM.yaw-=p0.ax[2]*2.4*dt;CAM.pitch=clamp(CAM.pitch+p0.ax[3]*1.8*dt,-.08,1.25);}
 const s1={mx:0,my:0,block:false,press:{}};
 s1.mx=(KEY.KeyD?1:0)-(KEY.KeyA?1:0);s1.my=(KEY.KeyW?1:0)-(KEY.KeyS?1:0);s1.block=!!(KEY.KeyL||KEY.ShiftLeft)||TOUCH.block;
 if(TOUCH.joy.on){s1.mx+=TOUCH.joy.x;s1.my+=TOUCH.joy.z;}
 for(const k in kbP1){if(kbP1[k]){s1.press[k]=1;kbP1[k]=0;}}
 if(p0.on){const dpx=(p0.btn[15]?1:0)-(p0.btn[14]?1:0),dpy=(p0.btn[12]?1:0)-(p0.btn[13]?1:0);
  s1.mx+=p0.ax[0]+dpx;s1.my+=-p0.ax[1]+dpy;s1.block=s1.block||p0.btn[4];
  if(pressed(p0,2))s1.press.punch=1;if(pressed(p0,0))s1.press.kick=1;if(pressed(p0,3)||pressed(p0,6))s1.press.p1=1;if(pressed(p0,1)||pressed(p0,7))s1.press.p2=1;if(pressed(p0,5))s1.press.jump=1;}
 s1.mx=clamp(s1.mx,-1,1);s1.my=clamp(s1.my,-1,1);
 if(M.mode==='TPS'){F0.in.press={punch:0,kick:0,p1:0,p2:0,jump:0};TPSI.mx=s1.mx;TPSI.my=s1.my;TPSI.jump=!!s1.press.jump||TPSI.jump;TPSI.run=!!(KEY.ShiftLeft||KEY.ShiftRight)||(p0.on&&p0.btn[1]);
  TPS.fire=!!(INPUTLOOK.fire||KEY.KeyJ||(p0.on&&(p0.btn[7]||p0.btn[2])));if(p0.on&&pressed(p0,3))tpsReload();return;}
 if(M.state==='fight'){fighterInput(F0,s1,B);}
 if(M.twoP){const p1=PADS[1],s2={mx:0,my:0,block:false,press:{}};
  s2.mx=(KEY.ArrowRight?1:0)-(KEY.ArrowLeft?1:0);s2.my=(KEY.ArrowUp?1:0)-(KEY.ArrowDown?1:0);s2.block=!!KEY.ShiftRight;
  for(const k in kbP2){if(kbP2[k]){s2.press[k]=1;kbP2[k]=0;}}
  if(p1.on){const dpx=(p1.btn[15]?1:0)-(p1.btn[14]?1:0),dpy=(p1.btn[12]?1:0)-(p1.btn[13]?1:0);
   s2.mx+=p1.ax[0]+dpx;s2.my+=-p1.ax[1]+dpy;s2.block=s2.block||p1.btn[4];
   if(pressed(p1,2))s2.press.punch=1;if(pressed(p1,0))s2.press.kick=1;if(pressed(p1,3)||pressed(p1,6))s2.press.p1=1;if(pressed(p1,1)||pressed(p1,7))s2.press.p2=1;if(pressed(p1,5))s2.press.jump=1;}
  s2.mx=clamp(s2.mx,-1,1);s2.my=clamp(s2.my,-1,1);
  F1.ctl='human';if(M.state==='fight')fighterInput(F1,s2,B);}
 else F1.ctl='ai';
}
const K1={KeyJ:'punch',KeyK:'kick',KeyU:'p1',KeyI:'p2',Space:'jump'},K2={Comma:'punch',Slash:'kick',Semicolon:'p1',Quote:'p2',Period:'jump'};
function togglePause(){PAUSED=!PAUSED;statusMsg(PAUSED?'PAUSED':'RESUMED');}
function toggleCamMenu(){CAMMENU.open=!CAMMENU.open;if(CAMMENU.open)CAMMENU.sel=CAM.view;statusMsg(CAMMENU.open?'CAMERA MENU':'VIEW · '+VIEWS[CAM.view]);}
function camMenuMove(d){CAMMENU.sel=(CAMMENU.sel+d+VIEWS.length)%VIEWS.length;CAM.view=CAMMENU.sel;}
function nextView(){CAM.view=(CAM.view+1)%VIEWS.length;CAMMENU.sel=CAM.view;statusMsg('VIEW · '+VIEWS[CAM.view]);}
function setTOD(h){TOD.hour=h;TOD.auto=false;}
function toggle2P(){M.twoP=!M.twoP;M.wins=[0,0];M.round=1;if(M.mode==='FIGHT')startRound();statusMsg(M.twoP?'2 PLAYER · P2 = PAD 2 / ARROWS':'1 PLAYER VS CPU');}
function cycleOpp(d){M.opp=(M.opp+d+6)%6;setArch(world.entities[1],ARCH_KEYS[M.opp]);M.wins=[0,0];M.round=1;if(M.mode==='FIGHT')startRound();statusMsg('OPPONENT · '+ARCH[ARCH_KEYS[M.opp]].name);}
function cycleP1(){M.p1=(M.p1+1)%6;setArch(world.entities[0],ARCH_KEYS[M.p1]);M.wins=[0,0];M.round=1;if(M.mode==='FIGHT')startRound();statusMsg('P1 · '+ARCH[ARCH_KEYS[M.p1]].name);}
function setMode(m){M.mode=m;const e0=world.entities[0],T=e0.get('Transform'),F=e0.get('Fighter');
 if(m==='TPS'){setArch(e0,'op');T.pos=[0,0,0];T.yaw=0;F.state='free';F.vx=F.vz=0;F.dis=0;CAM.yaw=Math.PI;CAM.pitch=.17;CAM.dist=3.4;TPS.init();statusMsg('3RD PERSON · WASD · CLICK = FIRE · R RELOAD');}
 else{setArch(e0,ARCH_KEYS[M.p1]);M.wins=[0,0];M.round=1;startRound();statusMsg('FIGHT MODE');}}
function resetMatch(){M.wins=[0,0];M.round=1;world.entities[0].get('Fighter').en=30;world.entities[1].get('Fighter').en=30;if(M.mode==='FIGHT')startRound();}
function nextStage(){M.stage=(M.stage+1)%3;statusMsg('STAGE · '+['MOUNTAINS','CITY EDGE','METROPOLIS'][M.stage]);}
function raySphere(o,d,c,r){const oc=V3.sub(o,c),b=V3.dot(oc,d),cc=V3.dot(oc,oc)-r*r,disc=b*b-cc;if(disc<0)return -1;const t=-b-Math.sqrt(disc);return t>0?t:-1;}
// ----- third-person mode: gun + drones -----
const TPSI={mx:0,my:0,jump:false,run:false};
const TPS={ready:false,fire:false,ammo:30,max:30,last:-1,rel:0,score:0,drones:[],recoil:0,hit:0,
 init:function(){if(this.ready){this.drones.forEach(d=>d.alive=true);return;}this.ready=true;
  for(let i=0;i<5;i++){const a=i/5*6.28+Math.random()*.6,r=7+Math.random()*5.5;this.drones.push({pos:[Math.cos(a)*r,0,Math.sin(a)*r],bob:Math.random()*6.28,alive:true,t:0});}}};
function tpsReload(){if(TPS.rel<=0&&TPS.ammo<TPS.max){TPS.rel=1.4;statusMsg('RELOADING…');}}
function updateTPS(dt,w){
 const e=w.entities[0],T=e.get('Transform'),F=e.get('Fighter'),R=e.get('Rig'),B=camBasis();
 const mx=TPSI.mx,my=TPSI.my,m=Math.min(1,Math.hypot(mx,my));
 let wx=B.r[0]*mx+B.f[0]*my,wz=B.r[1]*mx+B.f[1]*my;const wl=Math.hypot(wx,wz);if(wl>.001){wx/=wl;wz/=wl;}
 const aiming=TPS.fire,base=aiming?.85:(TPSI.run?3.6:1.5),tg=wl>.05?base*m:0,sp=Math.hypot(F.vx,F.vz);
 const nsp=sp+(tg-sp)*Math.min(1,dt*7);if(wl>.05){F.vx=wx*nsp;F.vz=wz*nsp;}else{F.vx*=.8;F.vz*=.8;}
 if(TPSI.jump&&!F.air){F.vy=JUMPV*.8;F.air=true;}TPSI.jump=false;
 if(F.air){F.y+=F.vy*dt;F.vy-=G_*dt;if(F.y<=0){F.y=0;F.vy=0;F.air=false;}}
 T.pos[0]+=F.vx*dt;T.pos[2]+=F.vz*dt;T.pos[1]=F.y;const r=Math.hypot(T.pos[0],T.pos[2]);if(r>15){T.pos[0]*=15/r;T.pos[2]*=15/r;}
 const fwdA=CAM.yaw+Math.PI;let yT=T.yaw;if(aiming)yT=fwdA;else if(Math.hypot(F.vx,F.vz)>.2)yT=Math.atan2(F.vx,F.vz);T.yaw=lerpAngle(T.yaw,yT,Math.min(1,dt*9));
 TPS.recoil*=Math.max(0,1-dt*9);
 if(TPS.rel>0){TPS.rel-=dt;if(TPS.rel<=0){TPS.ammo=TPS.max;statusMsg('RELOADED');}}
 if(TPS.fire&&TPS.rel<=0&&w.t-TPS.last>.11){if(TPS.ammo<=0)tpsReload();else{TPS.ammo--;TPS.last=w.t;TPS.recoil=1;tpsShoot(T,R);}}
 for(const d of TPS.drones){d.bob+=dt*1.6;if(!d.alive){d.t+=dt;if(d.t>1.6){const a=Math.random()*6.28,rr=7+Math.random()*5.5;d.pos=[Math.cos(a)*rr,0,Math.sin(a)*rr];d.alive=true;d.t=0;}}}
 TPS.hit-=dt;}
function tpsShoot(T,R){
 const gi=BIDX.gun,fy=T.yaw,mz=[R.pos[gi*3]+Math.sin(fy)*.5,R.pos[gi*3+1]+.0,R.pos[gi*3+2]+Math.cos(fy)*.5];
 const dir=V3.norm(V3.sub(CAM.target,CAM.eye));let bt=40,hd=null;
 for(const d of TPS.drones){if(!d.alive)continue;const t=raySphere(CAM.eye,dir,[d.pos[0],1.2+Math.sin(d.bob)*.18,d.pos[2]],.62);if(t>0&&t<bt){bt=t;hd=d;}}
 const hp=V3.add(CAM.eye,V3.scale(dir,bt));
 for(let i=0;i<16;i++)emit(V3.lerp(mz,hp,i/16),[0,0,0],[1.4,1.1,.5],.1,2.6,0,0);
 burst(mz,12,8,[1.4,1,.3],[1.2,.6,.2],.1,3,0);
 if(hd){hd.alive=false;hd.t=0;TPS.score++;TPS.hit=.15;burst([hd.pos[0],1.2,hd.pos[2]],110,10,[1.4,.3,.1],[1.5,1.2,.3],.8,3.5,0);statusMsg('TARGET ELIMINATED · SCORE '+TPS.score);}
 else if(bt<40)burst(hp,10,5,[1.2,1,.5],[.5,1,1],.3,2.5,2);}
// ----- camera -----
function updateCamera(dt,w){
 const e0=w.entities[0],e1=w.entities[1],aT=e0.get('Transform'),bT=e1.get('Transform');
 if(M.mode==='TPS'){CAM.yaw-=INPUTLOOK.dx*.0055;CAM.pitch=clamp(CAM.pitch+INPUTLOOK.dy*.0055,-.08,1.25);INPUTLOOK.dx=INPUTLOOK.dy=0;
  const tgt=[aT.pos[0],aT.pos[1]+1.18,aT.pos[2]],k=clamp(dt*6,0,1);for(let i=0;i<3;i++)CAM.target[i]+=(tgt[i]-CAM.target[i])*k;
  const cp=Math.cos(CAM.pitch),sp=Math.sin(CAM.pitch),dd=CAM.dist*CAMMENU.zoom;
  CAM.eye=[CAM.target[0]+dd*Math.sin(CAM.yaw)*cp,CAM.target[1]+dd*sp,CAM.target[2]+dd*Math.cos(CAM.yaw)*cp];CAM.fov+=(55-CAM.fov)*Math.min(1,dt*4);return;}
 const dx=bT.pos[0]-aT.pos[0],dz=bT.pos[2]-aT.pos[2],sep=Math.hypot(dx,dz),mid=[(aT.pos[0]+bT.pos[0])/2,0,(aT.pos[2]+bT.pos[2])/2];
 CAM.ang=lerpAngle(CAM.ang,Math.atan2(dx,dz),Math.min(1,dt*5));
 const sd=[-Math.cos(CAM.ang),0,Math.sin(CAM.ang)],ax=[Math.sin(CAM.ang),0,Math.cos(CAM.ang)],z=CAMMENU.zoom,dist=clamp(4.2+sep*.85,5.2,11)*z;
 let eye,tg,fov=50;
 switch(CAM.view){
  case 0:eye=[mid[0]+sd[0]*dist,1.55,mid[2]+sd[2]*dist];tg=[mid[0],1.15,mid[2]];break;
  case 1:eye=[mid[0]+sd[0]*dist*1.5,3.4,mid[2]+sd[2]*dist*1.5];tg=[mid[0],.9,mid[2]];fov=58;break;
  case 2:eye=[aT.pos[0]-ax[0]*2.1+sd[0]*1.1,2.0,aT.pos[2]-ax[2]*2.1+sd[2]*1.1];tg=[bT.pos[0],1.3,bT.pos[2]];fov=56;break;
  case 3:eye=[mid[0]+sd[0]*dist*.85,.45,mid[2]+sd[2]*dist*.85];tg=[mid[0],1.55,mid[2]];fov=46;break;
  case 4:eye=[mid[0]+sd[0]*.4,dist*1.7,mid[2]+sd[2]*.4];tg=[mid[0],0,mid[2]];fov=52;break;
  default:{const cp=Math.cos(CAM.pitch),sp=Math.sin(CAM.pitch),d2=dist*1.1;eye=[mid[0]+d2*Math.sin(CAM.yaw)*cp,1+d2*sp,mid[2]+d2*Math.cos(CAM.yaw)*cp];tg=[mid[0],1.2,mid[2]];}}
 const k=Math.min(1,dt*(CAM.view===5?10:6));
 for(let i=0;i<3;i++){CAM.eye[i]+=(eye[i]-CAM.eye[i])*k;CAM.target[i]+=(tg[i]-CAM.target[i])*k;}CAM.fov+=(fov-CAM.fov)*Math.min(1,dt*4);}
const INPUTLOOK={dx:0,dy:0};
// ----- animation system -----
function aimArms(pose,an,F,dt){
 an.ready=an.ready===undefined?.62:an.ready;an.ready+=((TPS.fire?1:.62)-an.ready)*Math.min(1,dt*10);
 const R=an.ready,sw=Math.sin(an.t*1.3),tg={rArm:[1.3,-.12,.16],rFore:[.3,0,0],rHand:[-.95,0,0],lArm:[1.1,.15,.85],lFore:[.95,-.1,.5],lHand:[.2,0,0]};
 for(const k in tg){const a=pose.rot[k]||Z3,b=tg[k];pose.rot[k]=[a[0]+(b[0]-a[0])*R,a[1]+(b[1]-a[1])*R,a[2]+(b[2]-a[2])*R];}
 const ap=clamp(CAM.pitch-.12,-.12,1.1)*(TPS.fire?1:.4);pose.rot.spine=[pose.rot.spine[0]+ap*.3,pose.rot.spine[1],0];pose.rot.chest=[pose.rot.chest[0]+ap*.4,pose.rot.chest[1],0];
 const rc=TPS.recoil;if(rc>.01){pose.rot.rHand=[pose.rot.rHand[0]-rc*.3,0,0];pose.rot.rArm=[pose.rot.rArm[0]-rc*.12,pose.rot.rArm[1],pose.rot.rArm[2]];pose.root=[pose.root[0],pose.root[1],pose.root[2]-rc*.03];}}
function fighterPose(e,dt){
 const T=e.get('Transform'),F=e.get('Fighter'),an=e.get('Animator');an.t+=dt;const t=an.t;
 const fd=faceDir(T),vf=F.vx*fd[0]+F.vz*fd[1],vs=F.vx*fd[1]-F.vz*fd[0];let pose,key=F.state;
 if(M.mode==='TPS'){key='tps';pose=moveClip(t,vf,vs);const l=pose.rot;l.rArm=[.9,0,0];}
 else switch(F.state){
  case 'atk':pose=attackPose(F.mdef.anim,F.st,F.mdef.st,F.mdef.en,F.mdef.dur);key='atk'+F.mv;break;
  case 'hit':pose=mixPose(stance(t),POSES.hit,F.air?1:(.15+.85*clamp(1-F.st/(F.stun+1e-3),0,1))*smooth(F.st/.05));break;
  case 'down':{const s=clamp(F.st/.75,0,1),k=s<.15?s/.15:(s>.6?1-(s-.6)/.4:1);pose=mixPose(stance(t),POSES.ko,smooth(k));break;}
  case 'ko':pose=mixPose(stance(t),POSES.ko,smooth(F.st/.45));break;
  case 'win':{pose=mixPose(stance(t),POSES.win,smooth(F.st/.4));pose.root=[pose.root[0],pose.root[1]+Math.abs(Math.sin(t*5))*.05,pose.root[2]];break;}
  default:if(F.air){pose=jumpPose(F.vy);key='air';}else if(F.block){pose=mixPose(moveClip(t,vf,vs),POSES.block,.9);key='blk';}else{pose=moveClip(t,vf,vs);}}
 if(key!==an.prev){if(an.last)an.blendFrom=copyPose(an.last);an.blendT=0;an.prev=key;}
 if(an.blendT<1&&an.blendFrom){an.blendT=Math.min(1,an.blendT+dt/.09);pose=mixPose(an.blendFrom,pose,smooth(an.blendT));}
 pose=copyPose(pose);an.last=copyPose(pose);
 if(M.mode==='TPS')aimArms(pose,an,F,dt);
