function sysAnim(dt,w){
 const n=M.mode==='TPS'?1:2;
 for(let i=0;i<n;i++){const e=w.entities[i],T=e.get('Transform'),F=e.get('Fighter'),R=e.get('Rig'),pose=fighterPose(e,dt);
  computePose(pose,T.pos,T.yaw,R.mats,R.pos);
  for(let b=0;b<NB;b++)if(F.hot[b]>.7&&b!==BIDX.rFore&&b!==BIDX.lFore&&b!==BIDX.rShin&&b!==BIDX.rThigh&&b!==BIDX.rArm){
   const p=[T.pos[0]+(R.pos[b*3]-T.pos[0])*F.S,T.pos[1]+(R.pos[b*3+1]-T.pos[1])*F.S,T.pos[2]+(R.pos[b*3+2]-T.pos[2])*F.S];
   for(let k=0;k<3;k++)emit(p,[rnd(-1,1),rnd(-1,1),rnd(-1,1)],F.A.hot,.3+Math.random()*.2,3,3,0);}}}
// ===== SKY NOISE (JS port of the old shader noise) =====
function h1f(n){const s=Math.sin(n)*43758.5453;return s-Math.floor(s);}
function n1f(x){const i=Math.floor(x),f=x-i,t=f*f*(3-2*f);return h1f(i)+(h1f(i+1)-h1f(i))*t;}
function fb1f(x){return .5*n1f(x)+.25*n1f(x*2.07+3.1)+.125*n1f(x*4.3+7.7)+.0625*n1f(x*8.9+1.3);}
function h3f(x,y,z){return h1f(x*12.9898+y*78.233+z*37.719);}
// ===== STATIC WORLD SCENERY DATA (trees / rocks / crystals / grass / fireflies) =====
const WORLD_PTS=[];let FIREFLY0=0,FIREFLY1=0;
function buildWorldData(){
 const push=(x,y,z,c,kind,r)=>{const j=.8+Math.random()*.4;WORLD_PTS.push(x,y,z,c[0]*j,c[1]*j,c[2]*j,kind,r===undefined?Math.random():r);};
 const sph=(cx,cy,cz,r,n,c,kind,sy)=>{for(let i=0;i<n;i++){let x,y,z,l;do{x=rnd(-1,1);y=rnd(-1,1);z=rnd(-1,1);l=x*x+y*y+z*z;}while(l>1||l<1e-3);l=Math.sqrt(l);push(cx+x/l*r,cy+y/l*r*(sy||1),cz+z/l*r,c,kind);}};
 for(let i=0;i<20;i++){const a=Math.random()*6.2832,rad=17+Math.random()*26,x=Math.cos(a)*rad,z=Math.sin(a)*rad,h=2.2+Math.random()*3.2,s=.7+Math.random()*.75;
  const kind=Math.random(),cc=kind<.2?[.85,.4,.1]:(kind<.35?[.9,.7,.15]:[.15+Math.random()*.15,.5+Math.random()*.25,.14]);
  for(let j=0;j<14;j++){const t=Math.random(),th=Math.random()*6.2832,rr=.16*s*(1-t*.5);push(x+Math.cos(th)*rr,t*h,z+Math.sin(th)*rr,[.32,.2,.1],0);}
  for(let b=0;b<2;b++)sph(x+rnd(-.85,.85)*s,h+rnd(-.1,.8)*s,z+rnd(-.85,.85)*s,(1.0+Math.random()*1.0)*s,26,cc,1,.8);}
 for(let i=0;i<14;i++){const a=Math.random()*6.2832,rad=17+Math.random()*30,r=.5+Math.random()*1.6;sph(Math.cos(a)*rad,r*.4,Math.sin(a)*rad,r,26,[.34,.34,.37],2,.7);}
 for(let i=0;i<9;i++){const a=Math.random()*6.2832,rad=16+Math.random()*26,x=Math.cos(a)*rad,z=Math.sin(a)*rad,col=[[.2,1,1.2],[1.2,.3,1],[1.2,.9,.2]][i%3];
  for(let c=0;c<3;c++){const h=.8+Math.random()*2.2,ox=rnd(-.5,.5),oz=rnd(-.5,.5),tx=rnd(-.5,.5),tz=rnd(-.5,.5);
   for(let j=0;j<16;j++){const t=Math.random(),th=Math.random()*6.2832,rr=.16*(1-t);push(x+ox+tx*t+Math.cos(th)*rr,t*h,z+oz+tz*t+Math.sin(th)*rr,col,3);}}}
 for(let i=0;i<420;i++){const a=Math.random()*6.2832,rad=12+Math.random()*30;push(Math.cos(a)*rad,Math.random()*.5,Math.sin(a)*rad,[.2+Math.random()*.2,.55+Math.random()*.2,.15],5);}
 FIREFLY0=WORLD_PTS.length/8;
 for(let i=0;i<120;i++){const a=Math.random()*6.2832,rad=4+Math.random()*28;push(Math.cos(a)*rad,.6+Math.random()*2.4,Math.sin(a)*rad,[1.4,1.2,.3],4);}
 FIREFLY1=WORLD_PTS.length/8;
}
// stars (fixed dome strip)
const STARS=[];
(function(){for(let i=0;i<230;i++){const az=Math.random()*6.2832,el=.03+Math.pow(Math.random(),1.5)*.72;
 STARS.push({az:az,el:el,b:.5+Math.random()*.5,s:.9+Math.random()*1.3});}})();
// hex floor segments (world-space cache)
const HEXSEG=[];
(function(){const R=.95,rr=12.6,hexR=Math.sqrt(3)*R,hexH=1.5*R;
 for(let q=-26;q<=26;q++)for(let r=-26;r<=26;r++){const x=hexR*(q+r*.5),z=hexH*r;if(x*x+z*z>rr*rr)continue;
  for(let i=0;i<6;i++){const a1=Math.PI/3*i,a2=a1+Math.PI/3;HEXSEG.push(x+R*Math.cos(a1),z+R*Math.sin(a1),x+R*Math.cos(a2),z+R*Math.sin(a2));}}})();
// FXC random pool (per-effect procedural point randoms)
const FXCP=[];(function(){for(let i=0;i<520;i++)FXCP.push(Math.random()*6.2832,Math.random(),Math.random(),Math.random());})();

// ===== SVG RENDER SYSTEM =====
let VW=1280,VH=800,TANF=.466,TANH=.746,CX=640,CY=400,HORY=400;
const _P=new Float32Array(16),_V=new Float32Array(16),_VP=new Float32Array(16);
let FV=[0,0,1],RV=[1,0,0],UV=[0,1,0],EYE=[0,1.6,-5];
let SKYD=null,GNDD=null,HEXEL=null,RINGEL=null,WB=null,FXB=null,PTSB=null,SKYKEY='';
function projDir(d){
 const dep=V3.dot(d,FV);if(dep<.02)return null;
 const nx=V3.dot(d,RV)/dep/TANH,ny=V3.dot(d,UV)/dep/TANF;
 if(nx<-1.45||nx>1.45||ny<-1.6||ny>1.5)return [CX+nx*CX,CY-ny*CY,true];
 return [CX+nx*CX,CY-ny*CY,false];}
const _pp=[0,0];
function projPt(x,y,z){ // returns [ndcX,ndcY] or null; culls behind camera / far offscreen
 const w=_VP[3]*x+_VP[7]*y+_VP[11]*z+_VP[15];if(w<.18)return null;
 const nx=(_VP[0]*x+_VP[4]*y+_VP[8]*z+_VP[12])/w;
 if(nx<-1.25||nx>1.25)return null;
 const ny=(_VP[1]*x+_VP[5]*y+_VP[9]*z+_VP[13])/w;
 if(ny<-1.35||ny>1.35)return null;
 _pp[0]=nx;_pp[1]=ny;return _pp;}
function initSVGDOM(){
 SKYD={rect:$('skyRect'),g0:$('skyS0'),g1:$('skyS1'),grad:$('skyGrad'),aur:$('aurora'),stars:$('starsP'),
  sunH:$('sunHalo'),sunD:$('sunDisc'),moonH:$('moonHalo'),moonD:$('moonDisc'),
  mtn:[$('mtn0'),$('mtn1'),$('mtn2')],cityB:$('cityB'),cityW:$('cityW')};
 GNDD={rect:$('gndRect'),g0:$('gndS0'),g1:$('gndS1'),grad:$('gndGrad'),arena:$('arenaEl'),a0:$('arS0'),a1:$('arS1')};
 HEXEL=$('floorHex');RINGEL=$('floorRing');
 WB=new BucketRenderer($('world-root'));
 FXB=new BucketRenderer($('fxc-root'));
 PTSB=new BucketRenderer($('pts-root'));}
// ----- sky -----
function drawSky(w){
 const azF=Math.atan2(FV[0],FV[2]);
 const hd=projDir([Math.sin(azF),0,Math.cos(azF)]);
 HORY=hd?hd[1]:(FV[1]<0?-80:VH+80);
 const key=TOD.hour.toFixed(2)+'|'+M.stage;
 if(key!==SKYKEY){SKYKEY=key;
  SKYD.g0.setAttribute('stop-color',cssC(TOD.zen));SKYD.g1.setAttribute('stop-color',cssC(TOD.hor));
  GNDD.g0.setAttribute('stop-color',cssC(TOD.fog));GNDD.g1.setAttribute('stop-color',cssC(TOD.ground));
  const fc=cssC(TOD.floor);GNDD.a0.setAttribute('stop-color',fc);GNDD.a1.setAttribute('stop-color',fc);
  SKYD.g0.parentNode.setAttribute('y2',Math.max(VH,60));}
 const hy=HORY;
 SKYD.rect.setAttribute('y',0);SKYD.rect.setAttribute('width',VW);SKYD.rect.setAttribute('height',clamp(hy+40,0,VH));
 // stars
 if(TOD.stars>.03){let s='';
  for(let i=0;i<STARS.length;i++){const st=STARS[i],ce=Math.cos(st.el),se=Math.sin(st.el);
   const p=projDir([Math.sin(st.az)*ce,se,Math.cos(st.az)*ce]);
   if(!p)continue;s+='M'+Math.round(p[0])+' '+Math.round(p[1])+'l.01 0';}
  SKYD.stars.setAttribute('d',s);SKYD.stars.setAttribute('opacity',(TOD.stars*(.65+.35*Math.sin(w.t*.9))).toFixed(2));}
 else SKYD.stars.setAttribute('opacity',0);
 // aurora band
 if(TOD.stars>.15){let s='',first=true;
  for(let i=0;i<=20;i++){const x=-40+i*(VW+80)/20,az=azF+Math.atan(((x-CX)/CX)*TANH);
   const el=.36+.1*Math.sin(az*3+w.t*.25)+.05*Math.sin(az*7-w.t*.4);
   const p=projDir([Math.sin(az)*Math.cos(el),Math.sin(el),Math.cos(az)*Math.cos(el)]);
   if(!p)continue;s+=(first?'M':'L')+Math.round(x)+' '+Math.round(p[1]);first=false;}
  if(!first){SKYD.aur.setAttribute('d',s);SKYD.aur.setAttribute('opacity',(TOD.stars*.3).toFixed(2));SKYD.aur.setAttribute('stroke-width',VH*.08);}
  else SKYD.aur.setAttribute('opacity',0);}
 else SKYD.aur.setAttribute('opacity',0);
 // sun & moon
 const sb=Math.min(1,(TOD.sun[0]+TOD.sun[1]+TOD.sun[2])*.7);
 const sp=projDir(TOD.sunDir);
 if(sp&&sb>.02){SKYD.sunD.setAttribute('cx',sp[0]);SKYD.sunD.setAttribute('cy',sp[1]);SKYD.sunD.setAttribute('r',VH*.015);
  SKYD.sunH.setAttribute('cx',sp[0]);SKYD.sunH.setAttribute('cy',sp[1]);SKYD.sunH.setAttribute('r',VH*.11);
  SKYD.sunD.setAttribute('opacity',sb.toFixed(2));SKYD.sunH.setAttribute('opacity',sb.toFixed(2));
  $('sunS0').setAttribute('stop-color',cssC(TOD.sun[0]*1.2+.4,TOD.sun[1]*1.1+.3,TOD.sun[2]+.2));}
 else{SKYD.sunD.setAttribute('opacity',0);SKYD.sunH.setAttribute('opacity',0);}
 const mp=projDir(TOD.moonDir);
 if(mp&&TOD.stars>.05){SKYD.moonD.setAttribute('cx',mp[0]);SKYD.moonD.setAttribute('cy',mp[1]);SKYD.moonD.setAttribute('r',VH*.012);
  SKYD.moonH.setAttribute('cx',mp[0]);SKYD.moonH.setAttribute('cy',mp[1]);SKYD.moonH.setAttribute('r',VH*.07);
  SKYD.moonD.setAttribute('opacity',TOD.stars.toFixed(2));SKYD.moonH.setAttribute('opacity',TOD.stars.toFixed(2));}
 else{SKYD.moonD.setAttribute('opacity',0);SKYD.moonH.setAttribute('opacity',0);}
 // mountains (3 fog layers)
 const city=[0,.55,1][M.stage],day=clamp(Math.sqrt(TOD.sun[0]*TOD.sun[0]+TOD.sun[1]*TOD.sun[1]+TOD.sun[2]*TOD.sun[2]),0,1);
 for(let L=0;L<3;L++){
  let s='',first=true;
  for(let i=0;i<=40;i++){const x=-30+i*(VW+60)/40,az=azF+Math.atan(((x-CX)/CX)*TANH);
   const f=fb1f(az*(2.2+L*1.4)+L*13.7);
   const el=(.03+.17*f)*(1-L*.25)*(1-city*.55)+.01;
   const p=projDir([Math.sin(az)*Math.cos(el),Math.sin(el),Math.cos(az)*Math.cos(el)]);
   if(!p)continue;s+=(first?'M':'L')+Math.round(x)+' '+Math.round(p[1]);first=false;}
  if(!first){s+='L'+(VW+30)+' '+Math.round(Math.min(hy+8,VH+40))+'L-30 '+Math.round(Math.min(hy+8,VH+40))+'Z';SKYD.mtn[L].setAttribute('d',s);}
  else SKYD.mtn[L].setAttribute('d','');
  let mc0=TOD.mtn[0]*(.4+.6*.6)*(.5+.5*day),mc1=TOD.mtn[1]*(.4+.6*.6)*(.5+.5*day),mc2=TOD.mtn[2]*(.4+.6*.6)*(.5+.5*day);
  const f2=(1-L*.33)*.5+.1;
  SKYD.mtn[L].setAttribute('fill',cssC(mc0+(TOD.hor[0]*.9-mc0)*f2,mc1+(TOD.hor[1]*.9-mc1)*f2,mc2+(TOD.hor[2]*.9-mc2)*f2));}
 // city skyline
 if(city>.01&&hy>-40&&hy<VH+40){
  const az1=azF-Math.atan(TANH*1.2),az2=azF+Math.atan(TANH*1.2);
  const c0=Math.floor(az1*60),c1=Math.ceil(az2*60);
  let sB='',sW='';let wc=0;const night=TOD.night;
  for(let ci=c0;ci<=c1;ci++){
   const m=fb1f(ci/60*1.3+4);const mask=m<.3?0:(m>.6?1:(m-.3)/.3);
   if(mask<=.05)continue;
   const bh=(.015+h1f(ci)*.1*Math.pow(h1f(ci+9),1.3)+.02*city)*mask;
   if(bh<.018)continue;
   const xa=CX+Math.tan(ci/60-azF)/TANH*CX,xb=CX+Math.tan((ci+1)/60-azF)/TANH*CX;
   const p=projDir([Math.sin(ci/60)*Math.cos(bh),Math.sin(bh),Math.cos(ci/60)*Math.cos(bh)]);
   if(!p)continue;
   const yt=p[1],yb=Math.min(hy+6,VH+40);
   if(yt>yb)continue;
   sB+='M'+Math.round(xa)+' '+Math.round(yb)+'L'+Math.round(xa)+' '+Math.round(yt)+'L'+Math.round(xb)+' '+Math.round(yt)+'L'+Math.round(xb)+' '+Math.round(yb)+'Z';
   if(night>.12&&wc<90&&h3f(ci,7,3)>.55){
    const nf=Math.min(5,Math.floor(bh*130));
    for(let wf=0;wf<nf&&wc<90;wf++){const wy=(wf+.6)/130;if(wy>bh)break;
     const wx=(ci*7+wf*13)%5;
     if(h3f(ci,wy*100,wx)>.72){
      const xw=xa+(xb-xa)*((wx+.5)/5),yw=yb-(wy/bh)*(yb-yt);
      sW+='M'+Math.round(xw-2)+' '+Math.round(yw-1.5)+'h4v3h-4Z';wc++;}}}}
  SKYD.cityB.setAttribute('d',sB);SKYD.cityB.setAttribute('opacity',1);
  SKYD.cityB.setAttribute('fill',cssC(TOD.mtn[0]*.3,TOD.mtn[1]*.3,TOD.mtn[2]*.3));
  SKYD.cityW.setAttribute('d',sW);SKYD.cityW.setAttribute('opacity',(night*.85).toFixed(2));}
 else{SKYD.cityB.setAttribute('opacity',0);SKYD.cityW.setAttribute('opacity',0);}
}
// ----- ground & floor -----
function drawGround(){
 const hy=HORY;
 const gy=clamp(hy,0,VH);
 GNDD.rect.setAttribute('y',gy);GNDD.rect.setAttribute('width',VW);GNDD.rect.setAttribute('height',VH-gy+1);
 GNDD.grad.setAttribute('y1',hy);GNDD.grad.setAttribute('y2',VH+60);
 let minx=1e9,maxx=-1e9,miny=1e9,maxy=-1e9,ok=0;
 const rim=[[17,0,0],[-17,0,0],[0,0,17],[0,0,-17],[0,0,0]];
 for(let i=0;i<5;i++){const p=projPt(rim[i][0],rim[i][1],rim[i][2]);if(!p)continue;ok++;
  const sx=CX+p[0]*CX,sy=CY-p[1]*CY;
  if(sx<minx)minx=sx;if(sx>maxx)maxx=sx;if(sy<miny)miny=sy;if(sy>maxy)maxy=sy;}
 if(ok>=3&&maxx>minx){GNDD.arena.setAttribute('cx',(minx+maxx)/2);GNDD.arena.setAttribute('cy',(miny+maxy)/2);
  GNDD.arena.setAttribute('rx',(maxx-minx)/2);GNDD.arena.setAttribute('ry',(maxy-miny)/2);GNDD.arena.setAttribute('opacity','.8');}
 else GNDD.arena.setAttribute('opacity',0);}
function drawFloor(w){
 let s='';const segs=HEXSEG.length>>2;
 for(let i=0;i<segs;i++){const j=i*4;
  const p1=projPt(HEXSEG[j],.01,HEXSEG[j+1]);if(!p1)continue;
  const x1=Math.round(CX+p1[0]*CX),y1=Math.round(CY-p1[1]*CY);
  const p2=projPt(HEXSEG[j+2],.01,HEXSEG[j+3]);if(!p2)continue;
  s+='M'+x1+' '+y1+'L'+Math.round(CX+p2[0]*CX)+' '+Math.round(CY-p2[1]*CY);}
 HEXEL.setAttribute('d',s);HEXEL.setAttribute('stroke',cssC(TOD.floor));
 let rs='',first=true;
 const wp=((w.t*1.9+1.5708)/1.6)%3.927;
 for(let k=0;k<2;k++){const r=wp+k*3.927,amp=Math.exp(-r*.14)*.9*(1-k*.55);
  if(amp<.04||r>13)continue;
  for(let i=0;i<=36;i++){const a=i/36*6.2832;
   const p=projPt(Math.cos(a)*r,.02,Math.sin(a)*r);if(!p)continue;
   rs+=(first?'M':'L')+Math.round(CX+p[0]*CX)+' '+Math.round(CY-p[1]*CY);first=false;}}
 if(!first){RINGEL.setAttribute('d',rs);RINGEL.setAttribute('opacity','.7');RINGEL.setAttribute('stroke',cssC(TOD.floor));}
 else RINGEL.setAttribute('opacity',0);}
// ----- world scenery -----
function drawWorldSVG(w){
 WB.begin();
 const P=WORLD_PTS,NC=FIREFLY1,t=w.t,night=TOD.night,amb=TOD.amb;
 for(let i=0;i<NC;i++){
  const o=i*8;let x=P[o],y=P[o+1],z=P[o+2];
  const kind=P[o+6],r=P[o+7];
  if(kind===4){
   if(night<.05)continue;
   x+=Math.sin(t*.7+r*60)*1.1;y+=Math.sin(t*.9+r*20)*.5;z+=Math.cos(t*.6+r*45)*1.1;}
  else if(kind===1||kind===5){
   x+=Math.sin(t*1.3+r*40+z*.3)*.06*(y*.35+.2);z+=Math.cos(t*1.1+r*30)*.05*(y*.3+.2);}
  const p=projPt(x,y,z);if(!p)continue;
  let cr,cg,cb,sz;
  if(kind===3){const gl=.5+1.6*night+.25*Math.sin(t*2+r*30);cr=P[o+3]*gl;cg=P[o+4]*gl;cb=P[o+5]*gl;sz=1.7;}
  else if(kind===4){const a=night*(.5+.5*Math.sin(t*3+r*50));cr=P[o+3];cg=P[o+4];cb=P[o+5];sz=1.7*(.4+.9*a);if(sz<.9)continue;}
  else{cr=P[o+3]*amb[0];cg=P[o+4]*amb[1];cb=P[o+5]*amb[2];sz=kind===5?.9:1.7;}
  const d=Math.max(.5,Math.hypot(x-EYE[0],y-EYE[1],z-EYE[2]));
  sz=clamp(sz*5/d,1.2,9);
  WB.push(Math.round(CX+p[0]*CX),Math.round(CY-p[1]*CY),quantC(cr,cg,cb),sz);}
 WB.flush();}
// ----- fighter cloud -----
function drawFighterSVG(e,other){
 const F=e.get('Fighter'),T=e.get('Transform'),R=e.get('Rig'),c=CLOUDS[F.key];
 if(!c||!c.data||!c.count)return;
 c.fade=Math.min(1,c.fade+.03);
 if(!e._br)e._br=new BucketRenderer(e._root);
 const br=e._br;br.begin();
 const A=F.A,mats=R.mats,N=c.count,pos=c.data.pos,col=c.data.col,skin=c.data.skin,ex=c.data.ex;
 const S=A.S,W=A.W,rx=T.pos[0],ry=T.pos[1],rz=T.pos[2];
 const fz=F.freeze>0||F.slow>0,fl=F.flash*.6;
 let mulR=fz?.75:1,mulG=fz?.9:1,mulB=fz?1.1:1;
 if(other&&other.key===F.key&&F.slot===1){mulR=1.5;mulG=.5;mulB=1.3;}
 const tnR=fl,tnG=fl+(fz?.15:0),tnB=fl+(fz?.3:0);
 const pulse=F.pulse,burstA=F.burst,dis=F.dis;
 const hot=F.hot,hotCol=A.hot,shim=A.fx.shim,jit=A.fx.jit,rise=A.fx.rise,orb=A.fx.orb||0;
 const gun=(M.mode==='TPS'&&F.key==='op')?1:0;
 const uPt=clamp(Math.pow(1e6/Math.max(c.count,1e4),.35),1,2.2);
 const t=world.t,rrx=rx,rry=ry+1.1*S,rrz=rz;
 const hcR=hotCol[0],hcG=hotCol[1],hcB=hotCol[2];
 for(let k=0;k<N;k++){
  const o3=k*3,o4=k*4;const kind=ex[o3+2];
  if(kind===1&&!gun)continue;
  let lx=pos[o3],ly=pos[o3+1],lz=pos[o3+2];
  if(kind===2){const an=t*orb,cs=Math.cos(an),sn=Math.sin(an);const nx2=lx*cs-lz*sn;lz=lx*sn+lz*cs;lx=nx2;}
  else if(kind===0||kind===3){lx*=W;lz*=W;}
  const i0=(skin[o4]+.5)|0,i1=(skin[o4+2]+.5)|0,w1=skin[o4+3];
  const m0=i0*16,m1=i1*16;
  let wx=mats[m0]*lx+mats[m0+4]*ly+mats[m0+8]*lz+mats[m0+12];
  let wy=mats[m0+1]*lx+mats[m0+5]*ly+mats[m0+9]*lz+mats[m0+13];
  let wz=mats[m0+2]*lx+mats[m0+6]*ly+mats[m0+10]*lz+mats[m0+14];
  if(w1>0){
   const ax2=mats[m1]*lx+mats[m1+4]*ly+mats[m1+8]*lz+mats[m1+12];
   const ay2=mats[m1+1]*lx+mats[m1+5]*ly+mats[m1+9]*lz+mats[m1+13];
   const az2=mats[m1+2]*lx+mats[m1+6]*ly+mats[m1+10]*lz+mats[m1+14];
   wx+=(ax2-wx)*w1;wy+=(ay2-wy)*w1;wz+=(az2-wz)*w1;}
  wx=rx+(wx-rx)*S;wy=ry+(wy-ry)*S;wz=rz+(wz-rz)*S;
  const r=ex[o3],h=hot[i0];
  const rvx=Math.sin(r*91.3),rvy=Math.cos(r*57.1),rvz=Math.sin(r*33.7+1);
  let sMul=1;
  if(kind===3){const f=fract(t*(.22+.3*rise)+r*7);wy+=f*1.5*S*(.3+rise);wx+=rvx*.14*f;wz+=rvz*.14*f;
   sMul=smooth(f/.12)*(1-f)*(.35+.65*rise);if(sMul<.06)continue;}
  let sh=shim;if(jit>0&&fract(r*13+t*9)>.72)sh+=jit*.035;
  if(sh>0){wx+=sh*Math.sin(t*2.2+r*47);wy+=sh*Math.sin(t*1.7+r*61);wz+=sh*Math.cos(t*2.6+r*34);}
  if(h>0){wx+=rvx*.045*h;wy+=rvy*.045*h;wz+=rvz*.045*h;}
  if(burstA>0){const cdx=wx-rrx,cdy=wy-rry,cdz=wz-rrz;const cl=Math.sqrt(cdx*cdx+cdy*cdy+cdz*cdz)+1e-3;
   const bf=burstA*(.4+r)*1.7;wx+=(cdx/cl*.9+rvx*.6)*bf;wy+=(cdy/cl*.9+rvy*.6)*bf;wz+=(cdz/cl*.9+rvz*.6)*bf;}
  if(dis>0){let dtd=dis*1.4-r*.4;if(dtd<0)dtd=0;else if(dtd>1)dtd=1;const df=dtd*dtd*2;
   wx+=rvx*.8*df;wy+=(.5+Math.abs(rvy)*1.8)*df;wz+=rvz*.8*df;}
  const pw=_VP[3]*wx+_VP[7]*wy+_VP[11]*wz+_VP[15];
  if(pw<.18)continue;
  const ndx=(_VP[0]*wx+_VP[4]*wy+_VP[8]*wz+_VP[12])/pw;
  if(ndx<-1.15||ndx>1.15)continue;
  const ndy=(_VP[1]*wx+_VP[5]*wy+_VP[9]*wz+_VP[13])/pw;
  if(ndy<-1.2||ndy>1.2)continue;
  const dxw=wx-EYE[0],dyw=wy-EYE[1],dzw=wz-EYE[2];
  const d=Math.sqrt(dxw*dxw+dyw*dyw+dzw*dzw);
  let sz=uPt*(ex[o3+1]>.5?2:1.2)*5/Math.max(d,.35)*(1+h*1.3+pulse*.5+burstA*1.2)*sMul;
  if(sz<1)continue;else if(sz>13)sz=13;
  let cr=col[o3]*mulR+tnR,cg=col[o3+1]*mulG+tnG,cb=col[o3+2]*mulB+tnB;
  let hm=h>1?1:h;hm*=.85;
  cr+=(hcR-cr)*hm;cg+=(hcG-cg)*hm;cb+=(hcB-cb)*hm;
  const pk=pulse*.45*(.4+(ex[o3+1]>.5?1:0));
  cr+=hcR*pk;cg+=hcG*pk;cb+=hcB*pk;
  const bb=1+burstA*.6;cr*=bb;cg*=bb;cb*=bb;
  br.push(Math.round(CX+ndx*CX),Math.round(CY-ndy*CY),quantC(cr,cg,cb),sz);}
 const dRoot=Math.hypot(rx-EYE[0],ry-EYE[1],rz-EYE[2]);
 const gop=(c.fade*clamp(1.3-dRoot/60,.1,1)).toFixed(2);
 if(gop!==e._gop){e._gop=gop;e._root.setAttribute('opacity',gop);}
 br.flush();}
// ----- procedural FX clouds (nova / pillar / zero / horizon / quake / flash / comets / drones) -----
function fxcDots(mode,pos,dir,r,h,tA,al,c1,c2,n){
 const q=fxQuality();
 n=Math.round(clamp(n/8000*520*q,36,520));
 for(let i=0;i<n;i++){
  const j=i*4,th=FXCP[j],u=FXCP[j+1],v=FXCP[j+2],w2=FXCP[j+3];
  let px=pos[0],py=pos[1],pz=pos[2],a=1;
  if(mode===0){const rr=r+(u-.5)*.9;const hh=v*v*h*(1-tA);px+=Math.cos(th)*rr;py+=.06+hh;pz+=Math.sin(th)*rr;a=1-tA*.6;}
  else if(mode===1){const hg=v*h;const rad=r*(.25+.75*u)*(1-.55*v);const an=th+hg*2.2+world.t*4*(.5+w2);
   px+=Math.cos(an)*rad;py+=hg;pz+=Math.sin(an)*rad;a=1-v*.5;}
  else if(mode===2){const cz=1-2*u;const sr=Math.sqrt(Math.max(0,1-cz*cz));const rr=r*(.92+.12*v);
   px+=Math.cos(th)*sr*rr;py+=cz*rr*.8+h;pz+=Math.sin(th)*sr*rr;a=(1-tA)*.9;}
  else if(mode===3){const f=fract(v+world.t*.7+w2*.3);const rad=r*(1-f);const an=th+f*5;
   px+=Math.cos(an)*rad;py+=(u-.5)*.5*(1-f)+h;pz+=Math.sin(an)*rad;a=smooth(f/.2);}
  else{const rr=r*Math.pow(u,.33);const cz=1-2*v;const sr=Math.sqrt(Math.max(0,1-cz*cz));
   const ox=Math.cos(th)*sr,oy=cz,oz=Math.sin(th)*sr;const tail=w2*w2*r*5*h;
   const dl=Math.sqrt(dir[0]*dir[0]+dir[1]*dir[1]+dir[2]*dir[2])||1;
   const dxn=dir[0]/dl,dyn=dir[1]/dl,dzn=dir[2]/dl;
   let rtx=-dzn,rtz=dxn;const rl=Math.sqrt(rtx*rtx+rtz*rtz);if(rl<1e-4){rtx=1;rtz=0;}else{rtx/=rl;rtz/=rl;}
   const upx=-rtz*dyn,upy=rtz*dxn-rtx*dzn,upz=rtx*dyn;
   const ang=world.t*6+tail*3,ca=Math.cos(ang),sa=Math.sin(ang),sw=Math.sin(w2*20+world.t*8)*.12*r*w2;
   const om=1-w2*.5;
   px+=(ox*om)-dxn*tail+(rtx*ca+upx*sa)*sw;
   py+=(oy*om)-dyn*tail+(upy*sa)*sw;
   pz+=(oz*om)-dzn*tail+(rtz*ca+upz*sa)*sw;
   a=1-w2*.7;}
  const p=projPt(px,py,pz);if(!p)continue;
  const d=Math.max(.5,Math.hypot(px-EYE[0],py-EYE[1],pz-EYE[2]));
  let sz=(mode>3.5?1.7:1.9)*5/d*(.6+.4*a);if(sz>10)sz=10;
  const mv=fract(v*3+u*2);
  const fall=al*a*clamp(14/d,.3,1);
  const cr=(c1[0]+(c2[0]-c1[0])*mv)*1.15*fall,cg=(c1[1]+(c2[1]-c1[1])*mv)*1.15*fall,cb=(c1[2]+(c2[2]-c1[2])*mv)*1.15*fall;
  FXB.push(Math.round(CX+p[0]*CX),Math.round(CY-p[1]*CY),quantC(cr,cg,cb),sz);}
}
function drawGFXSVG(w){
 FXB.begin();
 for(const g of GFX){const k=g.t/g.dur;
  if(g.type==='nova'){const h=g.a.A.hot;
   fxcDots(2,g.pos,null,Math.max(.1,g.r),0,k,1,[1.5,1.3,.4],h,7000);
   fxcDots(0,[g.pos[0],0,g.pos[2]],null,Math.max(.1,g.r*1.05),.7,k,1,h,[1.5,1.3,.5],6000);}
  else if(g.type==='pillar'){
   if(g.t<.7)fxcDots(0,g.pos,null,1.5*(1-.2*Math.sin(g.t*18)),.2,0,.9,[1.5,.3,.05],[1.5,1,.2],2500);
   else fxcDots(1,g.pos,null,1.2,4.2,k,Math.min(1,(g.dur-g.t)*2.5),[1.6,.4,.05],[1.6,1.4,.3],8000);}
  else if(g.type==='zero'){
   fxcDots(2,[g.pos[0],.6,g.pos[2]],null,Math.max(.1,g.r),0,k,.8,[.5,1.3,1.8],[1.5,1.8,2],7000);
   fxcDots(0,g.pos,null,Math.max(.1,g.r),.9,k,1,[.5,1.3,1.8],[1.6,1.8,2],6000);}
  else if(g.type==='horizon'){
   const f=g.t<1.1?1:Math.max(0,1-(g.t-1.1)*2);
   fxcDots(3,g.pos,null,3.2*(g.t<1.1?1:1+(g.t-1.1)*3),0,k,f,[.6,.1,1.2],[1.8,.6,2],8000);}
  else if(g.type==='quake')
   fxcDots(0,g.pos,null,Math.max(.2,g.r),1.1,k,Math.max(0,1-k),[.5,.45,.3],[.6,1.5,.4],8000);
  else if(g.type==='flash')
   fxcDots(2,g.pos,null,.3+g.t*3.5,0,k,1,g.c1||[1.6,1.6,1],g.c2||[.6,.9,2],2500);}
 for(const p of PROJ){const sp=V3.len(p.vel)||1;
  fxcDots(4,p.pos,V3.scale(p.vel,1/sp),p.r,p.tail,0,1,p.c1,p.c2,p.n);}
 FXB.flush();}
function drawDronesSVG(){
 FXB.begin();
 for(const d of TPS.drones){if(!d.alive)continue;
  const pos=[d.pos[0],1.2+Math.sin(d.bob)*.18,d.pos[2]];
  fxcDots(2,pos,null,.5,0,0,1,[.9,.08,.2],[1.5,.4,1],4500);
  fxcDots(2,pos,null,.28,0,0,1,[1.5,.9,1],[1.5,.4,.9],1500);}
 FXB.flush();}
function drawFXPSVG(){
 PTSB.begin();
 for(const f of FXP){
  const p=projPt(f.p[0],f.p[1],f.p[2]);if(!p)continue;
  const a=f.life/f.max,d=Math.max(.4,Math.hypot(f.p[0]-EYE[0],f.p[1]-EYE[1],f.p[2]-EYE[2]));
  let sz=f.s*(.5+.5*a)*5/d;if(sz>16)sz=16;
  PTSB.push(Math.round(CX+p[0]*CX),Math.round(CY-p[1]*CY),f.ci,sz);}
 PTSB.flush();}
function sysRender(dt,w){
 DRAWCALLS=0;
 const asp=VW/Math.max(1,VH);
 let eye=CAM.eye;
 if(CAM.shake>.001){eye=[eye[0]+rnd(-1,1)*CAM.shake,eye[1]+rnd(-1,1)*CAM.shake,eye[2]+rnd(-1,1)*CAM.shake];CAM.shake*=Math.max(0,1-dt*7);}
 EYE=eye;
 M4.perspective(CAM.fov*Math.PI/180,asp,.1,400,_P);M4.lookAt(eye,CAM.target,[0,1,0],_V);M4.mul(_P,_V,_VP);
 TANF=Math.tan(CAM.fov*Math.PI/360);TANH=TANF*asp;CX=VW/2;CY=VH/2;
 FV=V3.norm(V3.sub(CAM.target,eye));RV=V3.norm(V3.cross(FV,[0,1,0]));UV=V3.cross(RV,FV);
 drawSky(w);drawGround();drawWorldSVG(w);drawFloor(w);
 const E0=w.entities[0],E1=w.entities[1];
 drawFighterSVG(E0,E1.get('Fighter'));
 if(M.mode==='FIGHT')drawFighterSVG(E1,E0.get('Fighter'));
 if(M.mode==='FIGHT')drawGFXSVG(w);else drawDronesSVG();
 drawFXPSVG();
}

