  el('circle',{r:27,'class':'btn btnA'},g);el('text',{y:4,'text-anchor':'middle','class':'lbl lblA',text:b[0]},g);
  g.addEventListener('pointerdown',function(e){e.stopPropagation();if(b[1]==='block')TOUCH.block=true;else if(M.mode==='TPS'&&b[1]==='punch')INPUTLOOK.fire=true;else if(b[1]==='jump'){kbP1.jump=1;}else kbP1[b[1]]=1;});
