function sysHUD(dt,w){
 _hudT+=dt;if(_hudT<.05||!HUDR.timer)return;const d=_hudT;_hudT=0;
 const F0=w.entities[0].get('Fighter'),F1=w.entities[1].get('Fighter'),fight=M.mode==='FIGHT';
 HUDR.tpsG.style.display=fight?'none':'';HUDR.ch.style.display=fight?'none':'';
 HUDR.bars.forEach((b,s)=>{const F=s?F1:F0,vis=fight;[b.lag,b.fill,b.en,b.nm,b.pw,b.cb].forEach(n=>n.style.display=vis?'':'none');b.pips.forEach(p=>p.style.display=vis?'':'none');
  if(!vis)return;const f=clamp(F.hp/F.max,0,1);b.lagv+=(f-b.lagv)*Math.min(1,d*3);if(b.lagv<f)b.lagv=f;
  const W=HUDR.bw,x=s===0?b.x0+W*(1-f):b.x0,xl=s===0?b.x0+W*(1-b.lagv):b.x0;
  b.fill.setAttribute('width',(W*f).toFixed(1));b.fill.setAttribute('x',x.toFixed(1));b.lag.setAttribute('width',(W*b.lagv).toFixed(1));b.lag.setAttribute('x',xl.toFixed(1));
  const ew=W*clamp(F.en/100,0,1);b.en.setAttribute('width',ew.toFixed(1));b.en.setAttribute('x',(s===0?b.x0+W-ew:b.x0).toFixed(1));
  b.en.setAttribute('fill',F.en>=PW[F.A.pw[1]].cost?'#ffcc00':'#ff7bff');
  b.nm.textContent=(s===0?'P1 · ':(M.twoP?'P2 · ':'CPU · '))+F.A.name;
  b.pw.textContent=(s===0?'Y ':'')+PW[F.A.pw[0]].n+' · '+(s===0?'B ':'')+PW[F.A.pw[1]].n;
  b.cb.textContent=F.combo>1?F.combo+' HITS':'';
  for(let i=0;i<2;i++)b.pips[i].setAttribute('fill',M.wins[s]>i?'#ffcc00':'none');});
 HUDR.timer.textContent=fight?String(Math.max(0,Math.ceil(M.timer))):'';HUDR.rnd.textContent=fight?('ROUND '+M.round+(M.twoP?'':' · STAGE '+M.ladder)):'';
 HUDR.msg.textContent=fight?M.msg:'';
 if(!fight){HUDR.ammo.textContent=TPS.rel>0?'RELOADING':'AMMO '+TPS.ammo+'/'+TPS.max;HUDR.score.textContent='SCORE '+TPS.score;}
 let pts=0;for(let i=0;i<(fight?2:1);i++){const c=CLOUDS[w.entities[i].get('Fighter').key];if(c)pts+=c.count;}
 HUDR.tel[0].textContent='FPS '+FPS.toFixed(0)+' · PTS '+pts.toLocaleString('en-US')+' · FX '+FXP.length+' · PATHS '+DRAWCALLS;
 HUDR.tel[1].textContent='PURE SVG · '+M.mode+' · '+(M.twoP?'2 PLAYER':'1 PLAYER')+' · '+VIEWS[CAM.view]+' · '+todName()+(TOD.auto?' (AUTO)':'');
 HUDR.tel[2].textContent='PAD1 '+(PADS[0].on?PADS[0].id:'—')+' · PAD2 '+(PADS[1].on?PADS[1].id:'—');
 HUDR.tel[3].textContent='ECS '+w.entities.length+' ENT · '+w.entities.reduce((s,e)=>s+Object.keys(e.comps).length,0)+' COMP · '+w.systems.length+' SYS';
 HUDR.menuG.style.display=MENUSHOW?'':'none';HUDR.helpG.style.display=HELPSHOW?'':'none';
 HUDR.camG.style.display=CAMMENU.open?'':'none';
 HUDR.camItems.forEach((r,i)=>{const on=i===CAMMENU.sel;r.setAttribute('fill',on?'#00ffd0':'rgba(8,26,30,0.7)');});
 HUDR.camZoom.textContent='ZOOM '+Math.round(CAMMENU.zoom*100)+'%';
 [['bFight',M.mode==='FIGHT'],['bTps',M.mode==='TPS'],['b2p',M.twoP],['bCam',CAMMENU.open],['bAuto',TOD.auto],['bPause',PAUSED],['bHelp',HELPSHOW]].forEach(a=>{if(HUDR[a[0]])HUDR[a[0]].classList.toggle('act',!!a[1]);});
 if(HUDR.status&&performance.now()>_stT)HUDR.status.textContent=M.mode==='FIGHT'?'H HELP · C CAMERA MENU · G 3RD PERSON':'H HELP · G FIGHT MODE';
}
function showJoy(x,y){if(!HUDR.joy)return;HUDR.joy.setAttribute('transform','translate('+x+','+y+')');HUDR.knob.setAttribute('transform','translate(0,0)');}
function moveKnob(dx,dy){const m=46,l=Math.hypot(dx,dy);if(l>m){dx*=m/l;dy*=m/l;}HUDR.knob.setAttribute('transform','translate('+dx+','+dy+')');}
function doResize(){const w=window.innerWidth,h=window.innerHeight;document.documentElement.setAttribute('viewBox','0 0 '+w+' '+h);
 VW=w;VH=h;if(world)buildHUD(w,h);}
function attachInput(){
 window.addEventListener('keydown',function(e){const k=e.code;
  if(k.indexOf('Arrow')===0||k==='Space'||k==='Slash'||k==='Quote')e.preventDefault();if(e.repeat)return;KEY[k]=true;
  if(CAMMENU.open){if(k==='ArrowUp')camMenuMove(-1);else if(k==='ArrowDown')camMenuMove(1);else if(k==='ArrowLeft')CAMMENU.zoom=clamp(CAMMENU.zoom-.1,.6,1.6);else if(k==='ArrowRight')CAMMENU.zoom=clamp(CAMMENU.zoom+.1,.6,1.6);
   else if(k==='Enter'||k==='Space'||k==='Escape'||k==='KeyC')toggleCamMenu();return;}
  if(K1[k])kbP1[K1[k]]=1;if(K2[k]&&M.twoP)kbP2[K2[k]]=1;
  if(k==='KeyC')toggleCamMenu();else if(k==='KeyV')nextView();else if(k==='KeyT')nextTOD();else if(k==='KeyY')toggle2P();else if(k==='KeyO')cycleOpp(1);
  else if(k==='KeyG')setMode(M.mode==='FIGHT'?'TPS':'FIGHT');else if(k==='KeyF')cycleTier(1);else if(k==='KeyH')HELPSHOW=!HELPSHOW;else if(k==='KeyP')togglePause();else if(k==='KeyN')nextStage();
  else if(k==='KeyR'){if(M.mode==='TPS')tpsReload();else resetMatch();}});
 window.addEventListener('keyup',function(e){KEY[e.code]=false;});
 const sv=document.documentElement,ptrs=new Map();
 document.addEventListener('mousemove',function(e){if(document.pointerLockElement===sv){INPUTLOOK.dx+=e.movementX;INPUTLOOK.dy+=e.movementY;}});
 sv.addEventListener('mousedown',function(e){if(M.mode==='TPS'){if(document.pointerLockElement!==sv&&sv.requestPointerLock){try{sv.requestPointerLock();}catch(_){}}if(e.button===0)INPUTLOOK.fire=true;}});
 sv.addEventListener('mouseup',function(e){if(e.button===0)INPUTLOOK.fire=false;});
 sv.addEventListener('pointerdown',function(e){const touch=e.pointerType==='touch';if(touch){TOUCHMODE=true;if(HUDR.touchui)HUDR.touchui.style.display='';}
  try{sv.setPointerCapture(e.pointerId);}catch(_){}const mv=touch&&e.clientX<VW*.4,rec={x:e.clientX,y:e.clientY,move:mv,bx:e.clientX,by:e.clientY};
  if(mv){TOUCH.joy.on=true;showJoy(e.clientX,e.clientY);}ptrs.set(e.pointerId,rec);e.preventDefault();});
 sv.addEventListener('pointermove',function(e){const r=ptrs.get(e.pointerId);if(!r)return;const dx=e.clientX-r.x,dy=e.clientY-r.y;
  if(r.move){TOUCH.joy.x=clamp((e.clientX-r.bx)/46,-1,1);TOUCH.joy.z=clamp(-(e.clientY-r.by)/46,-1,1);moveKnob(e.clientX-r.bx,e.clientY-r.by);}
  else if(M.mode==='TPS'){INPUTLOOK.dx+=dx;INPUTLOOK.dy+=dy;}else if(CAM.view===5){CAM.yaw-=dx*.006;CAM.pitch=clamp(CAM.pitch+dy*.005,.02,1.3);}
  r.x=e.clientX;r.y=e.clientY;});
 const end=function(e){const r=ptrs.get(e.pointerId);if(r&&r.move){TOUCH.joy.on=false;TOUCH.joy.x=TOUCH.joy.z=0;if(HUDR.joy)HUDR.joy.setAttribute('transform','translate(90,'+(VH-90)+')');if(HUDR.knob)HUDR.knob.setAttribute('transform','translate(0,0)');}ptrs.delete(e.pointerId);};
 sv.addEventListener('pointerup',end);sv.addEventListener('pointercancel',end);
 sv.addEventListener('wheel',function(e){CAMMENU.zoom=clamp(CAMMENU.zoom*(1+e.deltaY*.0008),.6,1.6);e.preventDefault();},{passive:false});
 sv.addEventListener('contextmenu',function(e){e.preventDefault();});
 window.addEventListener('gamepadconnected',function(e){statusMsg('GAMEPAD: '+(e.gamepad.id||'').slice(0,28));});
}
let SDT=0,_lastT=0,_perfT=0;
function sysFight(dt,w){
 if(M.mode==='TPS'){updateTPS(dt,w);return;}
 const e0=w.entities[0],e1=w.entities[1],F0=e0.get('Fighter'),F1=e1.get('Fighter');F0.slot=0;F1.slot=1;
 if(!M.twoP)aiThink(e1,e0,dt);
 if(M.state!=='fight'){F0.in.mx=F0.in.mz=F1.in.mx=F1.in.mz=0;F0.in.block=F1.in.block=false;}
 const real=M.state==='fight';updateFighter(e0,e1,dt,real);updateFighter(e1,e0,dt,real);
 separate(e0.get('Transform'),F0,e1.get('Transform'),F1,M.arena);sysMatch(dt);}
function loop(ts){
 requestAnimationFrame(loop);if(!_lastT)_lastT=ts;let dt=(ts-_lastT)/1000;_lastT=ts;if(dt>.05)dt=.05;if(dt<=0)dt=.016;
 FPS+=(1/Math.max(dt,1e-3)-FPS)*.06;world.t+=dt;
 SDT=dt;if(HITSTOP>0){HITSTOP-=dt;SDT=dt*.06;}if(PAUSED||CAMMENU.open)SDT=0;
 for(const s of world.systems)s.update(s.real?dt:SDT,world);
 _perfT+=dt;if(FPS<22&&_perfT>4&&tierIdx>0){_perfT=0;tierIdx--;refreshClouds();statusMsg('AUTO-PERF · '+TIERS[tierIdx].toLocaleString('en-US')+' PTS');}}
function sys(name,fn,real){world.systems.push({name:name,update:fn,real:!!real});}
function boot(){
 world=new World();
 makeFighter(world,'operator','op',0);makeFighter(world,'rival',ARCH_KEYS[1],1);
 world.create('camera').add(new C('OrbitCam',{}));world.create('skybox').add(new C('Sky',{}));world.create('arena').add(new C('WorldCloud',{}));
 sys('IN',sysInput,true);sys('FIGHT',sysFight);sys('PROJ',function(dt){if(M.mode==='FIGHT'){updateProj(dt);updateGFX(dt);}});sys('FX',function(dt){stepFX(dt);});
 sys('ANIM',sysAnim);sys('TOD',function(dt){if(TOD.auto)TOD.hour+=dt*.35;updateTOD();},true);sys('CAM',updateCamera,true);sys('RENDER',sysRender,true);sys('HUD',sysHUD,true);
 initSVGDOM();buildWorldData();
 doResize();window.addEventListener('resize',doResize);attachInput();updateTOD();
 world.entities[0]._root=$('f0-root');world.entities[1]._root=$('f1-root');
 setArch(world.entities[0],'op');setArch(world.entities[1],ARCH_KEYS[1]);
 startRound();statusMsg('PURE SVG VECTOR PARTICLES · BACK/SHARE OR C = CAMERA MENU');
 window.__FIGHT={world:world,M:M,CAM:CAM,TOD:TOD,TPS:TPS};
 requestAnimationFrame(loop);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
